import React from 'react';
import { Box, Button, Typography } from '@mui/material';
import { styled } from '@mui/material/styles';
import { useNavigate } from 'react-router-dom';
import mioLogo from '../assets/찐로고.png';
import { GoogleLogin, CredentialResponse } from '@react-oauth/google';
// import GoogleIcon from '@mui/icons-material/Google'; // 또는 직접 SVG/이미지 사용

// MIO 로고 (임시 텍스트, 추후 이미지로 교체 가능)
const MioLogo = styled(Typography)(({ theme }) => ({
  fontSize: '4rem',
  fontWeight: 'bold',
  color: theme.palette.primary.main,
  textAlign: 'center',
  margin: theme.spacing(4, 0), // 로고 위아래 마진 조정
}));

const LoginPageOuterContainer = styled(Box)({
  display: 'flex',
  flexDirection: 'column',
  minHeight: '100vh',
  backgroundColor: '#F8F9FA', // Figma의 전체 배경색과 유사하게
});

// Typography를 기반으로 하되, as prop을 통해 HTML 태그를 변경할 수 있도록 함
const HeaderBar = styled(Typography)(({ theme }) => ({
  paddingTop: theme.spacing(2),
  paddingBottom: theme.spacing(2),
  fontWeight: theme.typography.fontWeightMedium,
  textAlign: 'center',
  width: '100%',
  backgroundColor: '#FFFFFF', // 상단 "로그인" 바 배경색
}));

const LoginPageContent = styled(Box)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'space-between', // 로고와 버튼을 상하로 분산시키기 위해
  flexGrow: 1,
  width: '100%',
  padding: theme.spacing(4),
  paddingBottom: theme.spacing(8), // 하단 여백 추가
  boxSizing: 'border-box',
}));

const LogoContainer = styled(Box)({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  flexGrow: 1, // 로고가 중앙에 오도록 남은 공간 차지
});

const LoginButtonContainer = styled(Box)(({ theme }) => ({
  width: '100%',
  maxWidth: '320px',
  display: 'flex',
  justifyContent: 'center',
  // GoogleLogin 컴포넌트의 기본 스타일을 활용하므로, 내부 요소에 대한 직접적인 스타일링 최소화
  // 너비는 GoogleLogin의 width prop으로 제어
}));

// GoogleLoginButton을 다시 정의 (useGoogleLogin 훅과 함께 사용)
const GoogleLoginButton = styled(Button)(({ theme }) => ({
  width: '100%',
  padding: theme.spacing(1.5),
  backgroundColor: '#FFFFFF',
  color: '#757575',
  border: '1px solid #E0E0E0',
  textTransform: 'none',
  fontSize: '1rem',
  fontWeight: 500,
  '&:hover': {
    backgroundColor: '#F5F5F5',
    borderColor: '#DADCE0',
  },
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(1.5),
}));

// Google 아이콘 SVG
const GoogleIconSvg = () => ( // 타입을 React.FC에서 일반 함수형 컴포넌트로 변경
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M22.56 12.25C22.56 11.47 22.49 10.72 22.36 10H12V14.51H17.92C17.66 15.99 16.96 17.27 15.81 18.09V21.09H19.8C21.66 19.36 22.56 16.78 22.56 12.25Z" fill="#4285F4"/>
    <path d="M12 23C14.97 23 17.45 22.02 19.21 20.39L15.81 18.09C14.81 18.73 13.5 19.15 12 19.15C9.33 19.15 7.02 17.36 6.12 14.91H2.04V17.9C3.79 20.93 7.59 23 12 23Z" fill="#34A853"/>
    <path d="M6.12 14.91C5.88 14.22 5.75 13.48 5.75 12.73C5.75 11.98 5.88 11.24 6.12 10.55V7.55H2.04C1.32 8.99 0.91 10.65 0.91 12.73C0.91 14.81 1.32 16.47 2.04 17.9L6.12 14.91Z" fill="#FBBC05"/>
    <path d="M12 5.85C13.66 5.85 15.03 6.43 15.99 7.35L19.27 4.07C17.45 2.35 14.97 1.27 12 1.27C7.59 1.27 3.79 3.34 2.04 6.37L6.12 9.37C7.02 6.92 9.33 5.85 12 5.85Z" fill="#EA4335"/>
  </svg>
);

const LoginPage: React.FC = () => {
  const navigate = useNavigate();

  const handleLoginSuccess = async (credentialResponse: CredentialResponse) => {
    console.log('Google Login Success:', credentialResponse);
    const idToken = credentialResponse.credential;

    if (idToken) {
      try {
        const backendUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080';
        
        const response = await fetch(`${backendUrl}/auth/google`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ token: idToken }),
        });

        if (response.ok) {
          const data = await response.json();
          console.log('서버 응답 데이터:', data);
          
          // accessToken 저장
          localStorage.setItem('userToken', data.accessToken);
          
          // refreshToken 저장
          if (data.refreshToken) {
            localStorage.setItem('refreshToken', data.refreshToken);
          }
          
          // 서버에서 직접 사용자 ID 받기
          if (data.userId) {
            localStorage.setItem('userId', data.userId.toString());
            console.log('서버에서 받은 사용자 ID:', data.userId);
          }
          
          // JWT에서 name, email, 사용자 ID 파싱
          function parseJwt(token) {
            try {
              const base64Url = token.split('.')[1];
              const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
              const jsonPayload = decodeURIComponent(
                atob(base64)
                  .split('')
                  .map(function (c) {
                    return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
                  })
                  .join('')
              );
              return JSON.parse(jsonPayload);
            } catch (e) {
              return null;
            }
          }
          const payload = parseJwt(data.accessToken);
          if (payload) {
            // 이메일 유효성 검사 시작
            const userEmail = payload.email;
            if (userEmail) {
              const allowedDomain = '@daejin.ac.kr';
              const exceptionEmail = 'anes53027@gmail.com';
              if (!userEmail.endsWith(allowedDomain) && userEmail !== exceptionEmail) {
                alert('대진대학교 학생만 로그인이 가능합니다. (허용 이메일: *' + allowedDomain + ')');
                // 필요한 경우 localStorage에서 토큰 등 정리
                localStorage.removeItem('userToken');
                localStorage.removeItem('refreshToken');
                localStorage.removeItem('userId');
                localStorage.removeItem('userName');
                localStorage.removeItem('userEmail');
                return; // 로그인 처리 중단
              }
            } else {
              alert('이메일 정보를 가져올 수 없습니다. 다시 시도해주세요.');
              return; // 로그인 처리 중단
            }
            // 이메일 유효성 검사 끝

            localStorage.setItem('userName', payload.name || '');
            localStorage.setItem('userEmail', payload.email || '');
            
            // JWT에서 사용자 ID 저장 (서버에서 userId를 직접 제공하지 않는 경우 사용)
            if (!data.userId) {
              const jwtUserId = payload.id || payload.userId || payload.sub;
              if (jwtUserId) {
                localStorage.setItem('userId', jwtUserId.toString());
                console.log('JWT에서 추출한 사용자 ID:', jwtUserId);
              } else {
                console.warn('JWT에 사용자 ID 정보가 없습니다:', payload);
                
                // 이메일로 사용자 정보 조회
                if (payload.email) {
                  try {
                    console.log('이메일로 사용자 정보 조회 시도:', payload.email);
                    const userResponse = await fetch(`${backendUrl}/user/email/${encodeURIComponent(payload.email)}`, {
                      method: 'GET',
                      headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${data.accessToken}`
                      }
                    });
                    
                    if (userResponse.ok) {
                      const userData = await userResponse.json();
                      console.log('이메일로 조회한 사용자 정보:', userData);
                      
                      if (userData && userData.id) {
                        localStorage.setItem('userId', userData.id.toString());
                        console.log('이메일 조회로 얻은 사용자 ID:', userData.id);
                      } else {
                        console.warn('이메일 조회에서 사용자 ID를 찾을 수 없습니다:', userData);
                      }
                    } else {
                      console.error('이메일로 사용자 정보 조회 실패:', await userResponse.text());
                    }
                  } catch (error) {
                    console.error('이메일로 사용자 정보 조회 중 오류 발생:', error);
                  }
                }
              }
            }
            
            // 디버깅을 위해 전체 JWT 페이로드 로깅
            console.log('JWT 페이로드:', payload);
          }
          navigate('/');
        } else {
          const errorData = await response.json();
          console.error('Backend login failed:', errorData);
          alert(`로그인 실패: ${errorData.message || '서버 오류'}`);
        }
      } catch (error) {
        console.error('Error during backend login:', error);
        alert('로그인 중 오류가 발생했습니다.');
      }
    } else {
      console.error('Google ID Token not found.');
      alert('Google 로그인 정보를 가져오는데 실패했습니다.');
    }
  };

  const handleLoginError = () => {
    console.error('Google Login Failed');
    alert('Google 로그인에 실패했습니다. 다시 시도해주세요.');
  };

  return (
    <LoginPageOuterContainer>
      {/* HeaderBar 사용 시 as prop을 사용하여 HTML 태그 지정 */}
      <LoginPageContent>
        <LogoContainer>
          <img src={mioLogo} alt="MIO 로고" style={{ height: 32 }} />
        </LogoContainer>
        <LoginButtonContainer>
          <GoogleLogin
            onSuccess={handleLoginSuccess}
            onError={handleLoginError}
            useOneTap
            shape="rectangular"
            type="standard"
            size="large"
            logo_alignment="left"
            width="320px"
            theme="outline"
            locale="ko"
          />
        </LoginButtonContainer>
      </LoginPageContent>
    </LoginPageOuterContainer>
  );
};

export default LoginPage; 