import React, { useState } from 'react';
import { Box, AppBar, Toolbar, Typography, IconButton, Container, Tabs, Tab, Button } from '@mui/material';
import { Home, Search, Add, Person } from '@mui/icons-material';
import { styled } from '@mui/material/styles';
import { Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import Timeline from '../pages/Timeline';
import SearchPage from '../pages/Search';
import LocationSearchPage from '../pages/LocationSearchPage';
import PostDetailPage from '../pages/PostDetailPage';
import ApplicationsPage from '../pages/ApplicationsPage';
import PostCreatePage from '../pages/PostCreatePage';
import NotificationsPage from '../pages/NotificationsPage';
import Notifications from './Notifications';
import ProfilePage from '../pages/ProfilePage';
import ProfileEditPage from '../pages/ProfileEditPage';
import ReviewsPage from '../pages/ReviewsPage';
import PostEditPage from '../pages/PostEditPage';
import mioLogo from '../assets/찐로고.png';

const StyledAppBar = styled(AppBar)(({ theme }) => ({
  backgroundColor: 'white',
  boxShadow: 'none',
  borderBottom: '1px solid #EEEEEE'
}));

const Logo = styled(Typography)(({ theme }) => ({
  color: '#2D68FF',
  fontWeight: 700,
  fontSize: '24px',
  marginRight: theme.spacing(4)
}));

const StyledTabs = styled(Tabs)(({ theme }) => ({
  '& .MuiTabs-indicator': {
    backgroundColor: '#2D68FF',
    height: '3px'
  },
  '& .MuiTab-root': {
    fontSize: '16px',
    fontWeight: 600,
    color: '#666666',
    '&.Mui-selected': {
      color: '#2D68FF'
    }
  }
}));

const BottomNavigation = styled(Box)(({ theme }) => ({
  position: 'fixed',
  bottom: 0,
  left: 0,
  right: 0,
  display: 'flex',
  justifyContent: 'space-around',
  padding: theme.spacing(1.5),
  backgroundColor: theme.palette.background.paper,
  borderTop: '1px solid #EEEEEE',
  zIndex: theme.zIndex.appBar,
}));

const MainContent = styled(Box)(({ theme }) => ({
  flexGrow: 1,
  paddingTop: '120px',
  paddingBottom: '80px',
  height: '100vh',
  overflow: 'auto',
  backgroundColor: '#F8F9FA',
}));

const EmptyStateContainer = styled(Box)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  padding: theme.spacing(4),
  textAlign: 'center',
  marginTop: theme.spacing(4),
}));

const Layout = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [currentTab, setCurrentTab] = useState(0);

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setCurrentTab(newValue);
  };

  const handleNotificationClick = (postId: number) => {
    navigate(`/post/${postId}`);
  };

  const goToNotificationsPage = () => {
    navigate('/notifications');
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      <StyledAppBar position="fixed">
        <Toolbar sx={{ justifyContent: 'space-between' }}>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <img src={mioLogo} alt="MIO 로고" style={{ height: 32 }} />
          </Box>
          <Box>
            <Notifications onNotificationClick={handleNotificationClick} />
          </Box>
        </Toolbar>
      </StyledAppBar>
      
      <MainContent>
        <Container maxWidth="sm">
          <Routes>
            <Route path="/" element={<Timeline />} />
            <Route path="/search" element={<SearchPage />} />
            <Route path="/location-search" element={<LocationSearchPage />} />
            <Route path="/post/:postId" element={<PostDetailPage />} />
            <Route path="/post/edit/:id" element={<PostEditPage />} />
            <Route path="/applications/:postId" element={<ApplicationsPage />} />
            <Route path="/create" element={<PostCreatePage />} />
            <Route path="/profile" element={<ProfilePage />} />
            <Route path="/profile/edit" element={<ProfileEditPage />} />
            <Route path="/notifications" element={<NotificationsPage />} />
            <Route path="/reviews" element={<ReviewsPage />} />
            <Route path="/create-review/:postId" element={<div>후기 작성 페이지 (postId: {/* postId 파라미터 사용 예시*/})</div>} />
          </Routes>
        </Container>
      </MainContent>

      <BottomNavigation>
        <IconButton onClick={() => navigate('/')} color={location.pathname === '/' ? 'primary' : 'default'}>
          <Home />
        </IconButton>
        <IconButton onClick={() => navigate('/search')} color={location.pathname === '/search' ? 'primary' : 'default'}>
          <Search />
        </IconButton>
        <IconButton onClick={() => navigate('/create')} color={location.pathname === '/create' ? 'primary' : 'default'}>
          <Add />
        </IconButton>
        <IconButton onClick={() => navigate('/profile')} color={location.pathname === '/profile' ? 'primary' : 'default'}>
          <Person />
        </IconButton>
      </BottomNavigation>
    </Box>
  );
};

export default Layout; 