import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  Box, 
  Typography, 
  Paper, 
  Divider, 
  Button, 
  CircularProgress, 
  IconButton,
  Container,
  List,
  ListItem,
  ListItemText,
  Avatar,
  Chip,
  Alert
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { ArrowBack } from '@mui/icons-material';
import axios from 'axios';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';

const API_BASE_URL = 'http://localhost:8080';

// ApprovalOrReject 열거형 정의
enum ApprovalOrReject {
  APPROVAL = "APPROVAL",
  REJECT = "REJECT",
  WAITING = "WAITING"
}

// 백엔드 DTO와 일치하는 사용자 정보 인터페이스
interface UserDetailDto {
  id: number;
  email?: string;
  studentId?: string;
  profileImageUrl?: string;  // 파일 저장 경로
  name?: string;
  gender?: boolean;
  accountNumber?: string;
  verifySmoker?: boolean;
  roleType?: string;
  status?: string;
  mannerCount?: number;
  grade?: string;
  activityLocation?: string;
  accountApprovalStatus?: string;
}

// 참여 정보 인터페이스
interface ParticipateDto {
  participantId: number;
  postId: number;
  userId: number;
  postUserId: number;
  content: string;
  approvalOrReject: ApprovalOrReject;
  driverMannerFinish: boolean;
  passengerMannerFinish: boolean;
  verifyFinish: boolean;
  isDeleteYN: string;
  
  // 추가 필드
  gender: boolean;
  verifySmoker: boolean; 
  verifyGoReturn: boolean;
  
  // 사용자 정보를 별도로 저장
  userInfo?: UserDetailDto;
}

// 응답 메시지 DTO 인터페이스 추가
interface ParticipateMsgDto {
  msg: string;
}

// 게시글 상태 enum 추가
enum PostType {
  BEFORE_DEADLINE = "BEFORE_DEADLINE",
  DEADLINE = "DEADLINE",
  COMPLETED = "COMPLETED"
}

// 게시글 정보 인터페이스 추가
interface PostDto {
  postId: number;
  title: string;
  postType: PostType;
  // ... (필요한 다른 필드들)
}

const PageContainer = styled(Box)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  minHeight: '80vh',
  backgroundColor: theme.palette.background.default,
}));

const TopAppBar = styled(Paper)(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  padding: theme.spacing(1, 2),
  position: 'sticky',
  top: 0,
  zIndex: 1100,
  backgroundColor: theme.palette.background.paper,
  borderBottom: `1px solid ${theme.palette.divider}`,
}));

const ListContainer = styled(Container)(({ theme }) => ({
  flex: 1,
  padding: theme.spacing(2),
  paddingBottom: theme.spacing(2), // 하단 패딩 줄임
}));

const ApplicationItem = styled(Paper)(({ theme }) => ({
  marginBottom: theme.spacing(2),
  padding: theme.spacing(2),
  borderRadius: theme.shape.borderRadius,
  boxShadow: 'none',
  border: `1px solid ${theme.palette.divider}`,
}));

const ApplicationItemApproved = styled(Paper)(({ theme }) => ({
  marginBottom: theme.spacing(2),
  padding: theme.spacing(2),
  borderRadius: theme.shape.borderRadius,
  boxShadow: 'none',
  border: `1px solid ${theme.palette.primary.light}`,
  backgroundColor: 'rgba(45, 104, 255, 0.05)', // 승인된 항목에 약간의 배경색 추가
}));

const ApplicationActions = styled(Box)(({ theme }) => ({
  display: 'flex',
  justifyContent: 'flex-end',
  marginTop: theme.spacing(1),
  gap: theme.spacing(1),
}));

const ApplicationContent = styled(Typography)(({ theme }) => ({
  fontSize: '1rem',
  color: theme.palette.text.primary,
  marginTop: 0,
  marginBottom: theme.spacing(1.5),
}));

const UserAvatar = styled(Avatar)(({ theme }) => ({
  width: 48,
  height: 48,
  border: `1px solid ${theme.palette.divider}`,
}));

const ApplicationDate = styled(Typography)(({ theme }) => ({
  fontSize: '0.75rem',
  color: theme.palette.text.secondary,
  marginLeft: 'auto',
}));

const StatusChip = styled(Chip)(({ theme }) => ({
  fontSize: '0.75rem',
  height: 24,
}));

const BottomButtonContainer = styled(Box)(({ theme }) => ({
  padding: theme.spacing(2),
  backgroundColor: theme.palette.background.paper,
  borderTop: `1px solid ${theme.palette.divider}`,
}));

const ApplicationsPage: React.FC = () => {
  const { postId } = useParams<{ postId: string }>();
  const navigate = useNavigate();
  const [applications, setApplications] = useState<ParticipateDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<number | null>(null); // 현재 action 중인 참여ID
  const [post, setPost] = useState<PostDto | null>(null);
  const [loadingPost, setLoadingPost] = useState(true);
  const [loadingDeadline, setLoadingDeadline] = useState(false);
  const [loadingComplete, setLoadingComplete] = useState(false);

  // 참여 신청 목록 불러오기
  useEffect(() => {
    const fetchApplications = async () => {
      if (!postId) return;
      
      setLoading(true);
      setError(null);
      
      try {
        // JWT 토큰 가져오기
        const token = localStorage.getItem('userToken');
        const currentUserId = localStorage.getItem('userId');
        
        // 게시글 별 참여자 조회 API 호출
        const response = await axios.get<ParticipateDto[]>(
          `${API_BASE_URL}/${postId}/participants`,
          {
            headers: {
              'Content-Type': 'application/json',
              ...(token && { 'Authorization': `Bearer ${token}` })
            }
          }
        );
        
        console.log('참여 신청 목록:', response.data);
        
        // 참여자 목록이 없거나 빈 배열인 경우 처리
        if (!response.data || response.data.length === 0) {
          setApplications([]);
          setLoading(false);
          return;
        }
        
        // 참여자 목록을 임시 저장 - 게시글 작성자와 동일한 참여자는 제외
        const participants = response.data.filter(participant => {
          // 작성자 ID와 참여자 ID 비교
          return participant.userId !== participant.postUserId;
        });
        
        console.log('필터링된 참여 신청 목록:', participants);
        
        // 참여자가 없는 경우 처리
        if (participants.length === 0) {
          setApplications([]);
          setLoading(false);
          return;
        }
        
        // 각 참여자의 사용자 정보 조회 (병렬 처리)
        const participantsWithUserInfo = await Promise.all(
          participants.map(async (participant) => {
            if (!participant.userId) {
              console.warn(`참여자 ID ${participant.participantId}에 대한 userId가 없습니다.`);
              return participant;
            }
            
            try {
              // 사용자 정보 조회 API 호출
              const userResponse = await axios.get<UserDetailDto>(
                `${API_BASE_URL}/user/id/${participant.userId}`,
                {
                  headers: {
                    'Content-Type': 'application/json',
                    ...(token && { 'Authorization': `Bearer ${token}` })
                  }
                }
              );
              
              console.log(`사용자 ID ${participant.userId}의 정보:`, userResponse.data);
              
              // 사용자 정보 추가
              return {
                ...participant,
                userInfo: userResponse.data
              };
            } catch (error) {
              console.error(`사용자 ID ${participant.userId} 정보 조회 실패:`, error);
              // 에러가 발생해도 원래 참여자 정보는 유지
              return participant;
            }
          })
        );
        
        setApplications(participantsWithUserInfo);
      } catch (err) {
        console.error('참여 신청 목록 조회 실패:', err);
        setError('참여 신청 목록을 불러오는데 실패했습니다.');
      } finally {
        setLoading(false);
      }
    };
    
    fetchApplications();
  }, [postId]);

  // 게시글 정보 불러오기
  useEffect(() => {
    const fetchPostDetails = async () => {
      if (!postId) return;
      
      setLoadingPost(true);
      try {
        const token = localStorage.getItem('userToken');
        const response = await axios.get<PostDto>(
          `${API_BASE_URL}/detail/${postId}`,
          {
            headers: {
              'Content-Type': 'application/json',
              ...(token && { 'Authorization': `Bearer ${token}` })
            }
          }
        );
        setPost(response.data);
      } catch (err) {
        console.error('게시글 정보 조회 실패:', err);
        setError('게시글 정보를 불러오는데 실패했습니다.');
      } finally {
        setLoadingPost(false);
      }
    };

    fetchPostDetails();
  }, [postId]);

  // 참여 신청 승인 처리
  const handleApprove = async (participantId: number) => {
    setActionLoading(participantId);
    try {
      const token = localStorage.getItem('userToken');
      
      // 승인 API 호출
      const response = await axios.patch<ParticipateMsgDto>(
        `${API_BASE_URL}/${participantId}/participateAccept`,
        {},
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      
      console.log('승인 응답:', response.data);
      
      // 상태 업데이트
      setApplications(prev => 
        prev.map(app => 
          app.participantId === participantId 
            ? { ...app, approvalOrReject: ApprovalOrReject.APPROVAL } 
            : app
        )
      );
      
      // 서버 응답 메시지가 있으면 표시
      if (response.data?.msg) {
        alert(response.data.msg);
      } else {
        alert('신청이 승인되었습니다.');
      }
    } catch (err) {
      console.error('신청 승인 실패:', err);
      alert('신청 승인에 실패했습니다.');
    } finally {
      setActionLoading(null);
    }
  };

  // 참여 신청 거절 처리
  const handleReject = async (participantId: number) => {
    setActionLoading(participantId);
    try {
      const token = localStorage.getItem('userToken');
      
      // 거절 API 호출
      const response = await axios.patch<ParticipateMsgDto>(
        `${API_BASE_URL}/${participantId}/reject`,
        {},
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      
      console.log('거절 응답:', response.data);
      
      // 상태 업데이트
      setApplications(prev => 
        prev.map(app => 
          app.participantId === participantId 
            ? { ...app, approvalOrReject: ApprovalOrReject.REJECT } 
            : app
        )
      );
      
      // 서버 응답 메시지가 있으면 표시
      if (response.data?.msg) {
        alert(response.data.msg);
      } else {
        alert('신청이 거절되었습니다.');
      }
    } catch (err) {
      console.error('신청 거절 실패:', err);
      alert('신청 거절에 실패했습니다.');
    } finally {
      setActionLoading(null);
    }
  };

  // 마감하기 핸들러 수정
  const handleDeadline = async () => {
    if (!postId || !post) return;
    
    // PostType이 BEFORE_DEADLINE이 아닌 경우 처리하지 않음
    if (post.postType !== PostType.BEFORE_DEADLINE) {
      alert('마감할 수 없는 상태입니다.');
      return;
    }
    
    if (!window.confirm('정말로 게시글을 마감하시겠습니까?')) {
      return;
    }
    
    setLoadingDeadline(true);
    try {
      const token = localStorage.getItem('userToken');
      const response = await axios.patch<PostDto>(
        `${API_BASE_URL}/post/deadLine/${postId}`,
        {},
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      
      // 게시글 상태 업데이트
      setPost(response.data);
      
      alert('게시글이 마감되었습니다.');
    } catch (err) {
      console.error('게시글 마감 실패:', err);
      alert('게시글 마감에 실패했습니다.');
    } finally {
      setLoadingDeadline(false);
    }
  };

  // 운행 완료 핸들러 추가
  const handleComplete = async () => {
    if (!postId || !post) return;
    
    // PostType이 DEADLINE이 아닌 경우 처리하지 않음
    if (post.postType !== PostType.DEADLINE) {
      alert('완료할 수 없는 상태입니다.');
      return;
    }
    
    if (!window.confirm('정말로 운행을 완료하시겠습니까?')) {
      return;
    }
    
    setLoadingComplete(true);
    try {
      const token = localStorage.getItem('userToken');
      const response = await axios.patch<PostDto>(
        `${API_BASE_URL}/post/complete/${postId}`,
        {},
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      
      // 게시글 상태 업데이트
      setPost(response.data);
      
      alert('운행이 완료되었습니다.');
    } catch (err) {
      console.error('운행 완료 실패:', err);
      alert('운행 완료에 실패했습니다.');
    } finally {
      setLoadingComplete(false);
    }
  };

  // 신청 상태에 따른 UI 렌더링
  const renderApplicationItem = (application: ParticipateDto) => {
    const { participantId, content, approvalOrReject, userInfo, gender, verifySmoker, verifyGoReturn } = application;
    const studentId = userInfo?.studentId || '학번 없음';
    
    // 승인 상태에 따라 다른 스타일의 컨테이너 사용
    const ItemContainer = approvalOrReject === ApprovalOrReject.APPROVAL 
      ? ApplicationItemApproved 
      : ApplicationItem;
    
    return (
      <ItemContainer key={participantId}>
        {/* 사용자 정보와 신청 정보를 한 줄에 표시 */}
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 1.5 }}>
          {/* 프로필 사진 */}
          <UserAvatar src={userInfo?.profileImageUrl} alt={studentId} />
          
          {/* 학번 */}
          <Typography sx={{ 
            ml: 1.5, 
            mr: 0.75, 
            fontSize: '0.875rem', 
            color: 'text.secondary',
            fontWeight: 500
          }}>
            {studentId}
          </Typography>
          
          {/* 세로 구분선 */}
          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            mx: 1.25, 
            height: '100%'
          }}>
            <Divider orientation="vertical" flexItem sx={{ 
              height: '20px', 
              borderColor: 'rgba(0, 0, 0, 0.12)' 
            }} />
          </Box>
          
          {/* 신청 정보를 가로로 일렬로 배치 */}
          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: 2,
            fontSize: '0.875rem',
            color: 'text.secondary',
            flex: 1
          }}>
            <Typography variant="body2" sx={{ fontSize: '0.875rem' }}>
              {gender ? '여성' : '남성'}
            </Typography>
            <Typography variant="body2" sx={{ fontSize: '0.875rem' }}>
              흡연 {verifySmoker ? 'O' : 'X'}
            </Typography>
            <Typography variant="body2" sx={{ fontSize: '0.875rem' }}>
              {verifyGoReturn ? '등교' : '하교'}
            </Typography>
          </Box>
        </Box>
        
        {/* 신청 내용 */}
        <ApplicationContent>
          {content}
        </ApplicationContent>
        
        {/* 승인 상태 표시 - 거절된 경우만 Chip 표시, 승인된 경우는 제외 */}
        {approvalOrReject === ApprovalOrReject.REJECT && (
          <Box sx={{ mb: 1 }}>
            <StatusChip 
              label="거절됨" 
              color="error"
              variant="outlined"
              size="small"
            />
          </Box>
        )}
        
        {/* 액션 버튼 */}
        <ApplicationActions>
          {approvalOrReject === ApprovalOrReject.WAITING ? (
            // 대기 상태일 때 승인/거절 버튼 표시
            <>
              <Button 
                variant="outlined" 
                color="error" 
                onClick={() => handleReject(participantId)}
                disabled={actionLoading === participantId}
                size="small"
                sx={{ minWidth: '64px' }}
              >
                {actionLoading === participantId ? <CircularProgress size={20} /> : "거절"}
              </Button>
              <Button 
                variant="contained" 
                color="primary" 
                onClick={() => handleApprove(participantId)}
                disabled={actionLoading === participantId}
                size="small"
                sx={{ minWidth: '64px' }}
              >
                {actionLoading === participantId ? <CircularProgress size={20} /> : "승인"}
              </Button>
            </>
          ) : approvalOrReject === ApprovalOrReject.APPROVAL ? (
            // 승인 상태일 때 - 승인됨 텍스트만 표시
            <Typography 
              variant="body2" 
              color="primary" 
              sx={{ 
                fontWeight: 'bold',
                ml: 'auto',
                opacity: 0.8
              }}
            >
              승인됨
            </Typography>
          ) : null}
        </ApplicationActions>
      </ItemContainer>
    );
  };

  return (
    <PageContainer>
      <TopAppBar>
        <IconButton edge="start" onClick={() => navigate(-1)}>
          <ArrowBack />
        </IconButton>
        <Typography variant="h6" sx={{ ml: 2, flexGrow: 1 }}>
          받은 신청
        </Typography>
      </TopAppBar>
      
      <ListContainer maxWidth="sm">
        {/* 게시글 상태 알림 추가 */}
        {post?.postType === PostType.DEADLINE && (
          <Alert severity="info" sx={{ mb: 2 }}>
            이 게시글은 마감되었습니다.
          </Alert>
        )}
        {post?.postType === PostType.COMPLETED && (
          <Alert severity="success" sx={{ mb: 2 }}>
            이 게시글은 완료되었습니다.
          </Alert>
        )}

        {loadingPost ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
            <CircularProgress />
          </Box>
        ) : error ? (
          <Box sx={{ textAlign: 'center', mt: 4 }}>
            <Typography color="error">{error}</Typography>
            <Button variant="outlined" sx={{ mt: 2 }} onClick={() => navigate(-1)}>
              뒤로가기
            </Button>
          </Box>
        ) : applications.length === 0 ? (
          <Box sx={{ textAlign: 'center', mt: 4 }}>
            <Typography>아직 받은 신청이 없습니다.</Typography>
          </Box>
        ) : (
          <List disablePadding>
            {applications.map(application => (
              <React.Fragment key={application.participantId}>
                {renderApplicationItem(application)}
              </React.Fragment>
            ))}
          </List>
        )}
      </ListContainer>

      {/* 하단 버튼 수정 */}
      <Container maxWidth="sm" disableGutters>
        <BottomButtonContainer>
          {post?.postType === PostType.BEFORE_DEADLINE && (
            <Button
              variant="contained"
              color="error"
              fullWidth
              onClick={handleDeadline}
              disabled={loadingDeadline || post.postType !== PostType.BEFORE_DEADLINE}
            >
              {loadingDeadline ? <CircularProgress size={20} /> : "마감하기"}
            </Button>
          )}
          {(post?.postType === PostType.DEADLINE || post?.postType === PostType.COMPLETED) && (
            <Button
              variant="contained"
              color="success"
              fullWidth
              onClick={handleComplete}
              disabled={loadingComplete || post.postType === PostType.COMPLETED}
            >
              {loadingComplete ? (
                <CircularProgress size={20} />
              ) : post.postType === PostType.COMPLETED ? (
                "운행 종료"
              ) : (
                "운행 완료"
              )}
            </Button>
          )}
        </BottomButtonContainer>
      </Container>
    </PageContainer>
  );
};

export default ApplicationsPage; 