import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, TextField, IconButton, List, ListItem, ListItemText, CircularProgress, Typography, AppBar, Toolbar } from '@mui/material';
import { ArrowBack, Close, LocationOn } from '@mui/icons-material';
import axios from 'axios';
import { PostDto } from '../types/post'; // PostDto 타입 임포트
import { debounce } from 'lodash';

const API_BASE_URL = 'http://localhost:8080';

const LocationSearchPage: React.FC = () => {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<PostDto[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const fetchLocations = useCallback(
    debounce(async (query: string) => {
      if (query.trim() === '') {
        setSearchResults([]);
        setLoading(false);
        return;
      }
      setLoading(true);
      setError(null);
      try {
        const response = await axios.get<PostDto[]>(`${API_BASE_URL}/post/location2`, {
          params: { location: query },
        });
        setSearchResults(response.data);
      } catch (err) {
        console.error("Error fetching locations:", err);
        setError('검색 중 오류가 발생했습니다.');
        setSearchResults([]);
      }
      setLoading(false);
    }, 300), // 300ms 디바운스
    []
  );

  useEffect(() => {
    fetchLocations(searchQuery);
  }, [searchQuery, fetchLocations]);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(event.target.value);
  };

  const handleResultClick = (post: PostDto) => {
    // PostDto에 위도(latitude), 경도(longitude) 정보가 있다고 가정합니다.
    // 실제 PostDto 구조에 맞춰서 위도, 경도, 장소 이름 등을 전달해야 합니다.
    // 예시: navigate('/search', { state: { selectedPlace: { name: post.title, lat: post.latitude, lng: post.longitude, address: post.location } } });
    // 현재 PostDto에는 위도/경도 정보가 없으므로, 일단 location 문자열만 전달합니다.
    navigate('/search', { state: { selectedPlace: { name: post.title, address: post.location, postData: post } } });
  };

  const handleClearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <AppBar position="static" color="inherit" elevation={1}>
        <Toolbar sx={{ minHeight: '56px !important' }}>
          <IconButton edge="start" color="inherit" onClick={() => navigate(-1)} aria-label="back">
            <ArrowBack />
          </IconButton>
          <TextField
            fullWidth
            variant="standard"
            placeholder="장소 또는 주소 검색"
            value={searchQuery}
            onChange={handleInputChange}
            autoFocus
            InputProps={{
              disableUnderline: true,
              style: { fontSize: '1rem' },
            }}
            sx={{ ml: 1 }}
          />
          {searchQuery && (
            <IconButton edge="end" color="inherit" onClick={handleClearSearch} aria-label="clear search">
              <Close />
            </IconButton>
          )}
        </Toolbar>
      </AppBar>
      <Box sx={{ flexGrow: 1, overflowY: 'auto', p: loading || searchResults.length > 0 || error ? 2 : 0 }}>
        {loading && (
          <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', py: 3 }}>
            <CircularProgress size={24} />
            <Typography sx={{ ml: 1 }}>검색 중...</Typography>
          </Box>
        )}
        {!loading && error && (
          <Typography color="error" sx={{ textAlign: 'center', py: 3 }}>
            {error}
          </Typography>
        )}
        {!loading && !error && searchResults.length === 0 && searchQuery.length > 0 && (
          <Typography sx={{ textAlign: 'center', color: 'text.secondary', py: 3 }}>
            검색 결과가 없습니다.
          </Typography>
        )}
        {!loading && !error && (
          <List disablePadding>
            {searchResults.map((post) => (
              <ListItem
                button
                key={post.postId} // 고유한 key 필요
                onClick={() => handleResultClick(post)}
                divider
              >
                <LocationOn sx={{ mr: 1.5, color: 'text.secondary' }} />
                <ListItemText 
                  primary={post.title || post.location} // 제목이 없으면 location으로 대체
                  secondary={post.location} 
                />
              </ListItem>
            ))}
          </List>
        )}
      </Box>
    </Box>
  );
};

export default LocationSearchPage; 