import React, { useEffect, useRef, useState } from 'react';
import { Box, Paper, Typography, TextField, InputAdornment, useTheme, useMediaQuery } from '@mui/material';
import { styled } from '@mui/material/styles';
import { Event as EventIcon, LocationOn, Group, Search as SearchIcon, Explore } from '@mui/icons-material';
import { motion } from 'framer-motion';
import { useLocation, useNavigate } from 'react-router-dom';
import { PostDto } from '../types/post';
import PostCard, { PostCardData } from '../components/PostCard';

const SearchContainer = styled(motion.div)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  height: 'calc(100vh - 56px)',
  backgroundColor: theme.palette.background.default,
}));

const TopBar = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(1.5, 2),
  borderBottom: `1px solid ${theme.palette.divider}`,
  backgroundColor: theme.palette.background.paper,
}));

const MapContainer = styled(Box)({
  flexGrow: 1,
  width: '100%',
  position: 'relative',
});

const InfoCardContainer = styled(motion.div)(({ theme }) => ({
  position: 'absolute',
  bottom: theme.spacing(2),
  left: theme.spacing(2),
  right: theme.spacing(2),
  zIndex: 1000,
}));

const InfoCard = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(2),
  borderRadius: '12px',
  boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.1)',
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(2),
}));

const InfoItem = styled(Box)(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(0.5),
  fontSize: '0.875rem',
  color: theme.palette.text.secondary,
  '& .MuiSvgIcon-root': {
    fontSize: '16px',
  }
}));

interface LocationState {
  selectedPlace?: {
    name?: string;
    address: string;
    postData: PostDto;
  };
}

// PostDto를 PostCardData 형식으로 변환하는 함수
const convertToPostCardData = (postDto: PostDto): PostCardData => {
  return {
    postId: postDto.postId,
    title: postDto.title,
    content: postDto.content,
    createDate: postDto.createDate,
    targetDate: postDto.targetDate,
    targetTime: postDto.targetTime,
    location: postDto.location,
    numberOfPassengers: postDto.numberOfPassengers,
    participantsCount: postDto.participantsCount,
    viewCount: postDto.viewCount,
    cost: postDto.cost,
    category: postDto.category ? {
      id: postDto.category.categoryId,
      name: postDto.category.categoryName
    } : undefined,
    commentCount: 0,
    postStatus: '',
    modifiedDate: ''
  };
};

const SearchPage: React.FC = () => {
  const mapRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const location = useLocation();
  const state = location.state as LocationState | null;
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const [mapInstance, setMapInstance] = useState<any>(null);
  const [displayedPost, setDisplayedPost] = useState<PostDto | null>(null);
  const [searchBarText, setSearchBarText] = useState('장소, 주소 검색');

  useEffect(() => {
    if (window.kakao && window.kakao.maps && mapRef.current) {
      const container = mapRef.current;
      let initialCenter = new window.kakao.maps.LatLng(37.5665, 126.9780);
      let initialLevel = 7;

      if (state?.selectedPlace?.address && window.kakao.maps.services) {
        setSearchBarText(state.selectedPlace.name || state.selectedPlace.address);
        setDisplayedPost(state.selectedPlace.postData);
      }

      const options = {
        center: initialCenter,
        level: initialLevel,
      };
      const map = new window.kakao.maps.Map(container, options);
      setMapInstance(map);

      if (state?.selectedPlace?.address) {
        geocodeAndSetMap(map, state.selectedPlace.address, state.selectedPlace.postData);
      }
    }
  }, [state]);
  
  const geocodeAndSetMap = (map: any, address: string, postData?: PostDto) => {
    if (postData?.latitude && postData?.longitude) {
      // 게시글에 위도/경도가 있는 경우 직접 좌표 사용
      const coords = new window.kakao.maps.LatLng(postData.latitude, postData.longitude);
      map.setCenter(coords);
      map.setLevel(3, { animate: true });
      new window.kakao.maps.Marker({
        map: map,
        position: coords,
      });
      if(postData) setDisplayedPost(postData);
      setSearchBarText(postData?.title || address);
    } else {
      // 주소로 검색하는 경우
      const geocoder = new window.kakao.maps.services.Geocoder();
      geocoder.addressSearch(address, (result: any, status: any) => {
        if (status === window.kakao.maps.services.Status.OK && result.length > 0) {
          const coords = new window.kakao.maps.LatLng(result[0].y, result[0].x);
          map.setCenter(coords);
          map.setLevel(3, { animate: true });
          new window.kakao.maps.Marker({
            map: map,
            position: coords,
          });
          if(postData) setDisplayedPost(postData);
          setSearchBarText(postData?.title || address);
        } else {
          console.warn('Geocode search failed for address:', address);
        }
      });
    }
  };

  const handleSearchClick = () => {
    navigate('/location-search');
  };

  return (
    <SearchContainer
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <TopBar elevation={0} onClick={handleSearchClick} sx={{ cursor: 'pointer' }}>
        <TextField
          fullWidth
          variant="outlined"
          placeholder="장소, 주소 검색"
          value={searchBarText}
          InputProps={{
            readOnly: true,
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
            sx: { borderRadius: '8px', backgroundColor: '#f0f0f0', border: 'none', "& fieldset": { border: 'none' } }
          }}
          sx={{ '.MuiOutlinedInput-notchedOutline': { border: 0 } }}
        />
      </TopBar>

      <MapContainer ref={mapRef} />

      {displayedPost && (
        <InfoCardContainer
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ delay: 0.2, type: 'spring', stiffness: 120 }}
        >
          <PostCard
            post={convertToPostCardData(displayedPost)}
            onClick={(postId) => navigate(`/post/${postId}`)}
            isMobile={isMobile}
          />
        </InfoCardContainer>
      )}
    </SearchContainer>
  );
};

export default SearchPage; 