const KEY_STORAGE_KEY = 'crypto_key';

// ArrayBuffer를 Base64 문자열로 변환
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

// Base64 문자열을 ArrayBuffer로 변환
function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binary_string = atob(base64);
  const len = binary_string.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary_string.charCodeAt(i);
  }
  return bytes.buffer;
}

// 키 생성 또는 로드
async function getKey(): Promise<CryptoKey> {
  let keyJson = localStorage.getItem(KEY_STORAGE_KEY);
  if (keyJson) {
    try {
      const jwk = JSON.parse(keyJson);
      return await crypto.subtle.importKey(
        'jwk',
        jwk,
        { name: 'AES-GCM' },
        true,
        ['encrypt', 'decrypt']
      );
    } catch (error) {
      console.error('Error importing key, generating new one:', error);
      // 키 import 실패 시 새 키 생성
    }
  }

  const newKey = await crypto.subtle.generateKey(
    { name: 'AES-GCM', length: 256 },
    true,
    ['encrypt', 'decrypt']
  );
  const jwk = await crypto.subtle.exportKey('jwk', newKey);
  localStorage.setItem(KEY_STORAGE_KEY, JSON.stringify(jwk));
  return newKey;
}

// 텍스트 암호화 (AES-GCM)
export async function encryptText(plainText: string): Promise<{ cipherText: string, iv: string }> {
  if (!plainText) return { cipherText: '', iv: '' };
  try {
    const key = await getKey();
    const iv = crypto.getRandomValues(new Uint8Array(12)); // Initialization Vector (IV)
    const encodedText = new TextEncoder().encode(plainText);

    const cipherBuffer = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: iv },
      key,
      encodedText
    );

    const cipherText = arrayBufferToBase64(cipherBuffer);
    const ivString = arrayBufferToBase64(iv.buffer); // iv는 Uint8Array이므로 .buffer를 사용

    return { cipherText, iv: ivString };
  } catch (error) {
    console.error('Encryption failed:', error);
    throw error; // 또는 적절한 오류 처리
  }
}

// 텍스트 복호화 (AES-GCM)
export async function decryptText(cipherTextBase64: string, ivBase64: string): Promise<string> {
  if (!cipherTextBase64 || !ivBase64) return '';
  try {
    const key = await getKey();

    const cipherArrayBuffer = base64ToArrayBuffer(cipherTextBase64);
    const ivArrayBuffer = base64ToArrayBuffer(ivBase64);

    const decryptedBuffer = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: new Uint8Array(ivArrayBuffer) }, // IV는 ArrayBufferView 타입이어야 함
      key,
      cipherArrayBuffer
    );

    return new TextDecoder().decode(decryptedBuffer);
  } catch (error) {
    console.error('Decryption failed:', error);
    // 복호화 실패 시 빈 문자열 반환 (예: 데이터가 암호화되지 않았거나 키가 다른 경우)
    // 실제 환경에서는 더 강력한 오류 처리 필요
    return ''; 
  }
} 