const mapPostDtoToUiTimelineEvent = (dto: PostDto): UiTimelineEvent => {
  let startLocation = dto.location;
  let endLocation = '';
  
  // '/'로 분리된 주소/장소명 형식 처리
  if (dto.location && dto.location.includes('/')) {
    const parts = dto.location.split('/');
    startLocation = parts[0]?.trim(); // 주소
    endLocation = parts[1]?.trim(); // 장소명
  } 
  // 이전 형식인 '→' 기호로 구분된 형식도 계속 지원
  else if (dto.location && dto.location.includes('→')) {
    const parts = dto.location.split('→');
    startLocation = parts[0]?.trim();
    endLocation = parts[1]?.trim();
  }

  return {
    id: `post-${dto.postId}`,
    postId: dto.postId,
    type: dto.category?.categoryId === 1 ? 'carpool' : 'taxi',
    categoryName: dto.category?.categoryName || '',
    time: `${dayjs(dto.targetDate).format('YY.MM.DD (ddd)')} ${dto.targetTime}`,
    title: dto.title,
    location: dto.location || '장소 정보 없음',
    startLocation: startLocation,
    endLocation: endLocation,
    participants: `${dto.participantsCount || 0}/${dto.numberOfPassengers}`,
    maxParticipants: dto.numberOfPassengers,
    price: dto.cost ? `${dto.cost.toLocaleString()}원` : '가격 정보 없음',
    author: dto.user?.nickname || '익명',
    isMyPost: false,
    rawPostDto: dto,
  };
};

