import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import axios from 'axios';

const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement
);

// 전역 axios Authorization 헤더 설정
const initialToken = localStorage.getItem('userToken');
if (initialToken) {
  axios.defaults.headers.common['Authorization'] = `Bearer ${initialToken}`;
}

let isRefreshing = false;
let failedQueue: Array<{ resolve: (value?: any) => void, reject: (reason?: any) => void }> = [];

const processQueue = (error: any, token: string | null = null) => {
  failedQueue.forEach(prom => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

axios.interceptors.response.use(
  response => response,
  async error => {
    const originalRequest = error.config;

    const isUnauthorized = error.response && error.response.status === 401;
    let hasSpecificErrorMessage = false;

    if (error.response && error.response.data) {
      const responseData = error.response.data;
      let errorMessage = '';
      if (typeof responseData.message === 'string') {
        errorMessage = responseData.message;
      } else if (typeof responseData.error === 'string') { // "error": "Cannot invoke..." 같은 경우
        errorMessage = responseData.error;
      } else if (typeof responseData === 'string') {
        errorMessage = responseData;
      } else if (responseData.details && typeof responseData.details === 'string') { // Spring Boot 기본 에러 메시지 중 details 필드
        errorMessage = responseData.details;
      } else if (responseData.message && typeof responseData.message.message === 'string') { // 중첩된 메시지 구조의 가능성
        errorMessage = responseData.message.message;
      }
      
      // 디버깅을 위해 실제 에러 메시지 구조를 로깅해볼 수 있습니다.
      // console.log("Raw error response data:", responseData);
      // console.log("Extracted error message for check:", errorMessage);

      if (errorMessage.toLowerCase().includes("user") && errorMessage.includes("is null")) {
        hasSpecificErrorMessage = true;
      }
    }

    if ((isUnauthorized || hasSpecificErrorMessage) && !originalRequest._retry) {
      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        })
        .then(token => {
          originalRequest.headers['Authorization'] = 'Bearer ' + token;
          return axios(originalRequest);
        })
        .catch(err => {
          return Promise.reject(err); 
        });
      }

      originalRequest._retry = true;
      isRefreshing = true;

      const refreshToken = localStorage.getItem('refreshToken');
      if (!refreshToken) {
        isRefreshing = false;
        processQueue(new Error("No refresh token available."), null);
        localStorage.removeItem('userToken');
        // localStorage.removeItem('refreshToken'); // 이미 없지만 명시적 제거
        window.location.href = '/login';
        return Promise.reject(new Error("No refresh token available."));
      }

      try {
        const res = await axios.post('http://localhost:8080/reissue', { refreshToken });
        const { accessToken, refreshToken: newRefreshToken } = res.data;
        
        localStorage.setItem('userToken', accessToken);
        if (newRefreshToken) {
          localStorage.setItem('refreshToken', newRefreshToken);
        }
        axios.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
        originalRequest.headers['Authorization'] = `Bearer ${accessToken}`;
        
        processQueue(null, accessToken);
        return axios(originalRequest);
      } catch (e) {
        processQueue(e, null);
        localStorage.removeItem('userToken');
        localStorage.removeItem('refreshToken');
        window.location.href = '/login';
        return Promise.reject(e);
      } finally {
        isRefreshing = false;
      }
    }
    return Promise.reject(error);
  }
);

root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
); 