// 등급 정보 상수
const GRADES = ['F', 'D', 'D+', 'C', 'C+', 'B', 'B+', 'A-', 'A', 'A+', 'MIO 조교님', 'MIO 교수님'];

const GRADE_DEFINITIONS: Array<{ name: string, minScore: number, maxScore: number }> = [
  { name: 'F', minScore: -Infinity, maxScore: -1 },
  { name: 'D', minScore: 0, maxScore: 9 },
  { name: 'D+', minScore: 10, maxScore: 19 },
  { name: 'C', minScore: 20, maxScore: 29 },
  { name: 'C+', minScore: 30, maxScore: 39 },
  { name: 'B', minScore: 40, maxScore: 49 },
  { name: 'B+', minScore: 50, maxScore: 59 },
  { name: 'A-', minScore: 60, maxScore: 69 },
  { name: 'A', minScore: 70, maxScore: 79 },
  { name: 'A+', minScore: 80, maxScore: 89 },
  { name: 'MIO 조교님', minScore: 90, maxScore: 99 },
  { name: 'MIO 교수님', minScore: 100, maxScore: Infinity }
];

interface GradeDisplay {
  grades: string[];
  currentIndex: number;
}

// 현재 등급의 인덱스와 주변 등급들을 가져오는 함수
const getGradeDisplay = (currentGrade: string): GradeDisplay => {
  const currentIndex = GRADES.indexOf(currentGrade);
  if (currentIndex === -1) return { grades: ['정보 없음'], currentIndex: 0 };

  // 표시할 등급들 계산
  const displayGrades: Array<string> = [];
  
  // 현재 등급을 기준으로 이전 2개, 현재, 다음 1개 등급을 가져옴
  for (let i = -2; i <= 1; i++) {
    const gradeIndex = currentIndex + i;
    if (gradeIndex >= 0 && gradeIndex < GRADES.length) {
      displayGrades.push(GRADES[gradeIndex]);
    }
  }

  // 부족한 등급 채우기
  while (displayGrades.length < 4) {
    if (displayGrades[0] === GRADES[0]) {
      // 앞쪽이 최저 등급이면 뒤에 추가
      const nextGrade = GRADES[GRADES.indexOf(displayGrades[displayGrades.length - 1]) + 1];
      if (nextGrade) displayGrades.push(nextGrade);
    } else {
      // 그 외의 경우 앞에 추가
      const prevGrade = GRADES[GRADES.indexOf(displayGrades[0]) - 1];
      if (prevGrade) displayGrades.unshift(prevGrade);
    }
  }

  // 현재 등급의 위치를 찾음
  const relativeCurrentIndex = displayGrades.indexOf(currentGrade);

  return {
    grades: displayGrades,
    currentIndex: relativeCurrentIndex
  };
};

// 등급 계산 로직
const getCurrentGrade = (count?: number): string => {
  if (count === undefined || count === null) return '정보 없음';
  // GRADE_DEFINITIONS를 사용하여 등급 결정 (F와 MIO 교수님은 특별 처리)
  for (let i = GRADE_DEFINITIONS.length - 1; i >= 0; i--) {
    const gradeDef = GRADE_DEFINITIONS[i];
    if (gradeDef.name === 'MIO 교수님' && count >= gradeDef.minScore) {
      return gradeDef.name;
    }
    if (count >= gradeDef.minScore && count <= gradeDef.maxScore) {
      return gradeDef.name;
    }
  }
  if (count <= GRADE_DEFINITIONS.find(g => g.name === 'F')!.maxScore) {
     return 'F';
  }
  return '정보 없음'; // 안전장치
};

const getProgressBarWidth = (
  mannerCount?: number, 
  currentGradeName?: string, 
  relativeCurrentIndexInDisplayedWindow?: number
): number => {
  if (mannerCount === undefined || mannerCount === null || currentGradeName === '정보 없음' || relativeCurrentIndexInDisplayedWindow === undefined || relativeCurrentIndexInDisplayedWindow === -1) {
    return 0;
  }

  const gradeDef = GRADE_DEFINITIONS.find(g => g.name === currentGradeName);
  if (!gradeDef) return 0;

  // 현재 등급이 표시되는 4칸 중 몇 번째 칸인지 (0-indexed)
  // 이 값은 현재 등급 이전의 등급들이 차지하는 너비를 결정 (각 칸은 25%)
  const baseWidthPercentage = relativeCurrentIndexInDisplayedWindow * 30;

  let progressInCurrentGradeSegment = 0;

  if (gradeDef.minScore === -Infinity || gradeDef.maxScore === Infinity) {
    // F 등급 또는 MIO 교수님 등급은 해당 칸을 완전히 채움
    progressInCurrentGradeSegment = 25;
  } else {
    const numPointsInGrade = gradeDef.maxScore - gradeDef.minScore + 1;

    if (numPointsInGrade <= 0) { // 유효하지 않은 범위 (일어나면 안 됨)
      progressInCurrentGradeSegment = 0;
    } else if (numPointsInGrade === 1) { // 단일 점수로 구성된 등급 (예: minScore === maxScore)
      progressInCurrentGradeSegment = (mannerCount === gradeDef.minScore) ? 25 : 0; // 해당 점수면 세그먼트 채움
    } else {
      // 현재 등급 내에서 몇 번째 스텝인지 (1-indexed)
      const currentStepOrdinal = (mannerCount - gradeDef.minScore) + 1;
      // 현재 등급의 총 스텝 수
      const totalStepsOrdinal = numPointsInGrade;
      
      const progressRatio = Math.max(0, Math.min(1, currentStepOrdinal / totalStepsOrdinal));
      progressInCurrentGradeSegment = progressRatio * 25; // 현재 등급 칸(25%) 내에서의 진행도
    }
  }
  
  return Math.min(baseWidthPercentage + progressInCurrentGradeSegment, 100);
};

