import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Container, Typography, Tabs, Tab, CircularProgress, Paper, List, ListItem, Button, Divider, IconButton } from '@mui/material';
import { ArrowBack } from '@mui/icons-material';
import axios from 'axios';
import { MannerDto, MannerScore, MannerScoreDisplay, ReviewablePostDto } from '../types/manner';
import { PostDto, Page } from '../types/post'; // PostDto는 ReviewablePostDto와 중복될 수 있으므로, ReviewablePostDto로 통일하거나 필요한 부분만 가져올 수 있음
import ReceivedReviewCard from '../components/ReceivedReviewCard';
import WritableReviewCard from '../components/WritableReviewCard';
import WrittenReviewCard from '../components/WrittenReviewCard';

const API_BASE_URL = 'http://localhost:8080';

// Manner enum 추가
enum Manner {
  GOOD = "GOOD",
  NORMAL = "NORMAL",
  BAD = "BAD"
}

// MannerPassengerUpdateRequestDto 인터페이스 추가
interface MannerPassengerUpdateRequestDto {
  manner: Manner;
  content: string;
  postId: number;
}

const ReviewsPage: React.FC = () => {
  const navigate = useNavigate();
  const [tabValue, setTabValue] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [receivedReviews, setReceivedReviews] = useState<MannerDto[]>([]);
  const [writableReviews, setWritableReviews] = useState<ReviewablePostDto[]>([]); // Page<PostDto>의 content 부분
  const [writtenReviews, setWrittenReviews] = useState<MannerDto[]>([]);

  const userId = localStorage.getItem('userId'); // 또는 다른 방식으로 userId 가져오기

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  // API 호출 함수들 (일단 빈 함수로)
  const fetchReceivedReviews = async () => {
    if (!userId) return;
    setLoading(true); setError(null);
    try {
      const response = await axios.get<MannerDto[]>(`http://localhost:8080/manners/get/${userId}`);
      setReceivedReviews(response.data);
    } catch (err) {
      setError('받은 후기를 불러오는데 실패했습니다.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchWritableReviews = async () => {
    setLoading(true); 
    setError(null);
    try {
      const token = localStorage.getItem('userToken');
      
      const response = await axios.get<Page<ReviewablePostDto>>(`${API_BASE_URL}/post/review`, {
        headers: {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        },
        params: { page: 0, size: 10, sort: 'createDate,desc' }
      });

      setWritableReviews(response.data.content);
    } catch (err) {
      setError('작성 가능한 후기를 불러오는데 실패했습니다.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchWrittenReviews = async () => {
    if (!userId) return;
    setLoading(true); setError(null);
    try {
      const response = await axios.get<MannerDto[]>(`http://localhost:8080/manners/post/${userId}`);
      setWrittenReviews(response.data);
    } catch (err) {
      setError('작성한 후기를 불러오는데 실패했습니다.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (tabValue === 0) {
      fetchReceivedReviews();
    } else if (tabValue === 1) {
      fetchWritableReviews();
    } else if (tabValue === 2) {
      fetchWrittenReviews();
    }
  }, [tabValue, userId]);

  const renderContent = () => {
    if (loading) return <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}><CircularProgress /></Box>;
    if (error) return <Typography color="error" sx={{ textAlign: 'center', p: 2 }}>{error}</Typography>;

    switch (tabValue) {
      case 0: // 받은 후기
        return receivedReviews.length > 0 ? (
          <List disablePadding sx={{width: '100%'}}>
            {receivedReviews.map((review) => (
              <ListItem key={review.id} disablePadding sx={{mb: 1.5}}>
                <ReceivedReviewCard review={review} />
              </ListItem>
            ))}
          </List>
        ) : <Typography sx={{textAlign: 'center', p:2, mt:2}}>받은 후기가 없습니다.</Typography>;
      case 1: // 작성 가능한 후기
        return writableReviews.length > 0 ? (
          <List disablePadding sx={{width: '100%'}}>
            {writableReviews.map((post) => (
              <ListItem key={post.postId} disablePadding sx={{mb: 1}}>
                <WritableReviewCard post={post} />
              </ListItem>
            ))}
          </List>
        ) : <Typography sx={{textAlign: 'center', p:2, mt:2}}>작성 가능한 후기가 없습니다.</Typography>;
      case 2: // 작성한 후기
        return writtenReviews.length > 0 ? (
          <List disablePadding sx={{width: '100%'}}>
            {writtenReviews.map((review) => (
              <ListItem key={review.id} disablePadding sx={{mb: 1.5}}>
                <WrittenReviewCard review={review} />
              </ListItem>
            ))}
          </List>
        ) : <Typography sx={{textAlign: 'center', p:2, mt:2}}>작성한 후기가 없습니다.</Typography>;
      default:
        return null;
    }
  };

  return (
    <Container maxWidth="sm" sx={{ pt: 2, pb: 8 }}>
      <Paper elevation={0} sx={{ borderRadius: '12px', position: 'relative' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', p: 2, borderBottom: 1, borderColor: 'divider' }}>
          <IconButton onClick={() => navigate(-1)} sx={{ mr: 1 }}>
            <ArrowBack />
          </IconButton>
          <Typography variant="h6" fontWeight="bold">후기</Typography>
        </Box>
        <Tabs value={tabValue} onChange={handleTabChange} variant="fullWidth">
          <Tab label="받은 후기" />
          <Tab label="작성 가능한 후기" />
          <Tab label="작성한 후기" />
        </Tabs>
        <Box sx={{ p: {xs: 1, sm: 2} }}>
          {renderContent()}
        </Box>
      </Paper>
    </Container>
  );
};

export default ReviewsPage; 