// 카테고리 ID (카풀:1, 택시:2 등으로 가정)
const CATEGORY_MAP = {
  카풀: 1,
  택시: 2
};

// 카카오맵 API 타입 선언
declare global {
  interface Window {
    kakao: any;
  }
}

// 카카오맵 Place 타입 정의
interface KakaoPlace {
  place_name: string;
  address_name?: string;
  road_address_name?: string;
  x: string;
  y: string;
  id: string;
}

