const InputContainer = styled(Box)(({ theme }) => ({
  marginBottom: theme.spacing(3),
}));

interface PostCreateRequestDto {
  title: string;
  content: string;
  targetDate: string;
  targetTime: string;
  gender: boolean;
  verifySmoker: boolean;
  verifyGoReturn: boolean;
  numberOfPassengers: number;
  latitude: number;
  longitude: number;
  location: string;
  cost: number;
  region3Depth?: string;
}

interface SearchResult {
  id: string;
  name: string;
  address: string;
  region3Depth: string;
  latitude: number;
  longitude: number;
}

const PostCreatePage: () => JSX.Element = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState<number>(1);
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [isSubmitComplete, setIsSubmitComplete] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState<boolean>(false);
  
  // 최근 검색어를 상태로 관리
  const [recentSearchResults, setRecentSearchResults] = useState<SearchResult[]>([]);
  
  // 시간 및 분 선택 상태
  const [selectedHour, setSelectedHour] = useState<string>('');
  const [selectedMinute, setSelectedMinute] = useState<string>('');
  const [availableMinutes, setAvailableMinutes] = useState<string[]>(['00', '10', '20', '30', '40', '50']);
  
  // 추가적인 상태 변수들
  const [showMap, setShowMap] = useState<boolean>(false);
  const [selectedLocation, setSelectedLocation] = useState<SearchResult | null>(null);
  const mapRef = useRef<HTMLDivElement>(null);
  const markerRef = useRef<any>(null);
  const kakaoMapRef = useRef<any>(null);
  
  // 로컬스토리지에서 최근 검색어 불러오기
  useEffect(() => {
    const savedSearches = localStorage.getItem('recentLocations');
    if (savedSearches) {
      try {
        const parsed = JSON.parse(savedSearches);
        setRecentSearchResults(parsed);
      } catch (e) {
        console.error('최근 검색어 파싱 오류:', e);
        setRecentSearchResults([]);
      }
    }
  }, []);

  // 게시글 폼 데이터
  const [postData, setPostData] = useState<PostCreateRequestDto>({
    title: '',
    content: '',
    targetDate: '',
    targetTime: '',
    gender: false, // 기본값 남성
    verifySmoker: false, // 기본값 비흡연
    verifyGoReturn: true, // 기본값 등교
    numberOfPassengers: 1,
    latitude: 0,
    longitude: 0,
    location: '',
    cost: 0,
    region3Depth: ''
  });

  // 카테고리 선택 상태
  const [selectedCategory, setSelectedCategory] = useState<'카풀' | '택시'>('카풀');

  // 카카오맵 API를 사용한 검색 처리 함수
  const handleSearch = () => {
    if (!searchQuery.trim()) {
      return;
    }
    
    setIsSearching(true);
    
    // 카카오맵 API 호출
    if (window.kakao && window.kakao.maps) {
      // 장소 검색 객체 생성
      const ps = new window.kakao.maps.services.Places();
      
      // 키워드 검색 완료 시 호출되는 콜백함수
      const placesSearchCB = (data: any[], status: any) => {
        if (status === window.kakao.maps.services.Status.OK) {
          // 검색 결과를 SearchResult 형식으로 변환
          const results: SearchResult[] = data.map((item, index) => ({
            id: String(index),
            name: item.place_name,
            address: item.address_name,
            region3Depth: item.address_name.split(' ').slice(0, 3).join(' '), // 시/구/동까지만 저장
            latitude: parseFloat(item.y),
            longitude: parseFloat(item.x)
          }));
          
          setSearchResults(results);
        } else {
          // 검색 실패 시 빈 배열 설정
          setSearchResults([]);
        }
        setIsSearching(false);
      };
      
      // 키워드로 장소 검색
      ps.keywordSearch(searchQuery, placesSearchCB);
    } else {
      console.error('카카오맵 API가 로드되지 않았습니다.');
      setIsSearching(false);
      setSearchResults([]);
    }
  };

  // 지도 초기화 함수
  const initializeMap = useCallback((location: SearchResult) => {
    if (!mapRef.current) return;
    
    if (window.kakao && window.kakao.maps) {
      const options = {
        center: new window.kakao.maps.LatLng(location.latitude, location.longitude),
        level: 3
      };
      
      // 지도 생성
      const map = new window.kakao.maps.Map(mapRef.current, options);
      kakaoMapRef.current = map;
      
      // 마커 생성
      const markerPosition = new window.kakao.maps.LatLng(location.latitude, location.longitude);
      const marker = new window.kakao.maps.Marker({
        position: markerPosition,
        draggable: true // 드래그 가능하도록 설정
      });
      
      // 마커를 지도에 표시
      marker.setMap(map);
      markerRef.current = marker;
      
      // 마커 드래그 이벤트 리스너 등록
      window.kakao.maps.event.addListener(marker, 'dragend', function() {
        const position = marker.getPosition();
        const lat = position.getLat();
        const lng = position.getLng();
        
        // 새 위치의 주소 정보 가져오기
        const geocoder = new window.kakao.maps.services.Geocoder();
        geocoder.coord2Address(lng, lat, (result: any, status: any) => {
          if (status === window.kakao.maps.services.Status.OK) {
            const addressInfo = result[0];
            const address = addressInfo.address?.address_name || '';
            
            // 주변 장소 검색을 위한 Places 서비스 생성
            const ps = new window.kakao.maps.services.Places();
            
            // 좌표 기반 키워드 검색 (주변 POI 찾기)
            ps.keywordSearch('', (places: any, placeStatus: any) => {
              // 기본값으로 주소만 표시
              let locationName = '';
              let fullAddress = address;
              
              // region3depth 정보 가져오기
              let region3DepthValue = '';
              if (addressInfo.address?.region_3depth_name) {
                region3DepthValue = addressInfo.address.region_3depth_name;
              } else {
                region3DepthValue = extractRegion3Depth(address);
              }
              
              // 주변 장소 검색 (근방 500m)
              const options = {
                location: new window.kakao.maps.LatLng(lat, lng),
                radius: 500,
                sort: window.kakao.maps.services.SortBy.DISTANCE
              };
              
              ps.categorySearch('', function(categoryPlaces: any, categoryStatus: any) {
                if (categoryStatus === window.kakao.maps.services.Status.OK && categoryPlaces && categoryPlaces.length > 0) {
                  // 가장 가까운 POI 사용
                  const nearestPlace = categoryPlaces[0];
                  locationName = nearestPlace.place_name;
                  
                  // 최종 위치 정보 업데이트
                  const updatedLocation = {
                    ...location,
                    name: locationName,
                    latitude: lat,
                    longitude: lng,
                    address: address
                  };
                  setSelectedLocation(updatedLocation);
                  
                  // postData 업데이트 - 위치 정보 형식 변경: "주소/장소명"
                  setPostData({
                    ...postData,
                    latitude: lat,
                    longitude: lng,
                    location: `${address}/${locationName}`,
                    region3Depth: region3DepthValue
                  });
                } else {
                  // POI가 없는 경우 도로명이나 동네 이름 등 주소 정보만 사용
                  const buildingName = addressInfo.road_address?.building_name || '';
                  const roadName = addressInfo.road_address?.road_name || '';
                  
                  if (buildingName) {
                    locationName = buildingName;
                  } else if (roadName) {
                    locationName = roadName;
                  } else {
                    locationName = addressInfo.address?.region_3depth_name || '위치';
                  }
                  
                  // 최종 위치 정보 업데이트
                  const updatedLocation = {
                    ...location,
                    name: locationName,
                    latitude: lat,
                    longitude: lng,
                    address: address
                  };
                  setSelectedLocation(updatedLocation);
                  
                  // postData 업데이트 - 위치 정보 형식 변경: "주소/위치설명"
                  setPostData({
                    ...postData,
                    latitude: lat,
                    longitude: lng,
                    location: `${address}/${locationName}`,
                    region3Depth: region3DepthValue
                  });
                }
              }, options);
            }, {
              location: new window.kakao.maps.LatLng(lat, lng),
              radius: 100
            });
          }
        });
      });
      
      // 맵 사이즈 변경 이벤트가 발생하면 지도 중심 재설정
      window.kakao.maps.event.addListener(map, 'idle', function() {
        map.relayout();
      });
    }
  }, [postData]);
  
  // 위치가 선택되면 지도 초기화
  useEffect(() => {
    if (showMap && selectedLocation && mapRef.current) {
      initializeMap(selectedLocation);
    }
  }, [showMap, selectedLocation, initializeMap]);

  // 위치 선택 처리 함수 수정
  const handleSelectLocation = (location: SearchResult) => {
    // 선택된 위치 저장
    setSelectedLocation(location);
    setShowMap(true);
    
    // 위치 정보 형식 변경: "주소명/장소명" 형식으로 저장
    setPostData({
      ...postData,
      location: `${location.address}/${location.name}`,
      latitude: location.latitude,
      longitude: location.longitude,
      region3Depth: location.region3Depth // 시/구/동까지만 저장
    });
    
    // 최근 검색어에 추가
    const isAlreadySaved = recentSearchResults.some(item => item.id === location.id);
    if (!isAlreadySaved) {
      const updatedRecent = [location, ...recentSearchResults].slice(0, 5); // 최대 5개만 유지
      setRecentSearchResults(updatedRecent);
      
      // 로컬스토리지에 저장
      try {
        localStorage.setItem('recentLocations', JSON.stringify(updatedRecent));
      } catch (e) {
        console.error('최근 검색어 저장 오류:', e);
      }
    }
    
    // 검색 상태 초기화
    setSearchQuery('');
    setSearchResults([]);
  };
  
  // 위치 선택 확인 (지도 화면에서 다음 단계로 이동)
  const confirmLocation = () => {
    setShowMap(false);
    setCurrentStep(3);
  };
  
  // 위치 재검색 (지도 화면에서 검색 화면으로 돌아가기)
  const resetLocationSearch = () => {
    setShowMap(false);
    setSelectedLocation(null);
  };

  // 주소에서 동 정보 추출 (예시)
  const extractRegion3Depth = (address: string): string => {
    // 실제로는 정규식이나 API를 통해 정확히 추출해야 합니다
    const parts = address.split(' ');
    // 임시로 마지막 부분을 동으로 가정
    return parts[parts.length - 1];
  };

  // 승객 수 증가
  const increasePassengers = () => {
    if (postData.numberOfPassengers < 8) {
      setPostData({
        ...postData,
        numberOfPassengers: postData.numberOfPassengers + 1
      });
    }
  };

  // 승객 수 감소
  const decreasePassengers = () => {
    if (postData.numberOfPassengers > 1) {
      setPostData({
        ...postData,
        numberOfPassengers: postData.numberOfPassengers - 1
      });
    }
  };

  // 게시글 제출 처리
  const handleSubmit = async () => {
    // 필수 항목 검증
    if (!postData.title || !postData.targetDate || !postData.targetTime || !postData.location || !postData.content) {
      alert('제목, 날짜, 시간, 위치, 내용은 필수 항목입니다. 모두 입력해주세요.');
      return;
    }

    setIsSubmitting(true);
    
    try {
      // 날짜와 시간 형식 검증 및 변환
      const formattedPostData = {
        ...postData,
        // HTML date input은 이미 'YYYY-MM-DD' 형식으로 반환
        // HTML time input은 'HH:MM' 형식으로 반환
      };
      
      // 토큰이 있다면 가져오기
      const token = localStorage.getItem('userToken');
      
      // 카테고리 ID 가져오기
      const categoryId = CATEGORY_MAP[selectedCategory];
      
      // API 호출
      const response = await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/post/${categoryId}`,
        formattedPostData,
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      
      console.log('게시글 생성 성공:', response.data);
      
      // 제출 완료 상태로 전환
      setIsSubmitComplete(true);
      
      // 성공 메시지 표시
      alert('게시글이 성공적으로 등록되었습니다!');
      
      // 타임라인 페이지로 이동
      navigate('/');
      
    } catch (error) {
      console.error('게시글 생성 실패:', error);
      alert('게시글 작성에 실패했습니다.');
    } finally {
      setIsSubmitting(false);
    }
  };

  // 폼 유효성 검사
  const isStepValid = (step: number): boolean => {
    switch (step) {
      case 1:
        return !!postData.title && !!postData.targetDate && !!postData.targetTime;
      case 2:
        // 2단계는 위치 선택 화면에서 showMap이 true이면서 selectedLocation이 있을 때만 유효
        return !showMap && !!postData.location;
      case 3:
        return true; // 3단계는 모든 옵션이 기본값이 있으므로 항상 유효
      case 4:
        return !!postData.content; // 4단계는 내용이 필수
      default:
        return false;
    }
  };

  // 다음 단계로 이동
  const goToNextStep = () => {
    if (isStepValid(currentStep) && currentStep < 4) {
      setCurrentStep(prev => prev + 1);
    } else if (!isStepValid(currentStep)) {
      alert('필수 항목을 모두 입력해주세요.');
    }
  };

  // 이전 단계로 이동
  const goToPrevStep = () => {
    if (currentStep > 1) {
      setCurrentStep(prev => prev - 1);
    } else {
      // 첫 단계에서 뒤로가기는 취소로 처리
      if (window.confirm('작성을 취소하시겠습니까? 작성한 내용은 저장되지 않습니다.')) {
        navigate(-1);
      }
    }
  };

  // 검색어 입력 시 자동 검색
  useEffect(() => {
    if (currentStep === 2 && searchQuery.length > 1) {
      const timer = setTimeout(() => {
        handleSearch();
      }, 300);

      return () => clearTimeout(timer);
    }
  }, [searchQuery, currentStep]);

  // selectedHour 또는 selectedMinute가 변경될 때 postData.targetTime 업데이트
  useEffect(() => {
    if (selectedHour && selectedMinute) {
      const newTime = `${selectedHour}:${selectedMinute}`;
      if (postData.targetTime !== newTime) {
        setPostData(prev => ({ ...prev, targetTime: newTime }));
      }
    } else {
      // 시간 또는 분이 선택되지 않은 경우 targetTime을 비움
      if (postData.targetTime !== '') {
        setPostData(prev => ({ ...prev, targetTime: '' }));
      }
    }
  }, [selectedHour, selectedMinute, postData.targetTime, setPostData]);

  // postData.targetTime이 변경될 때 selectedHour와 selectedMinute를 초기화/업데이트
  useEffect(() => {
    if (postData.targetTime) {
      const [hour, minute] = postData.targetTime.split(':');
      const validHours = ['07', '08', '09', '18', '19', '20'];
      
      let isValidMinuteForHour = false;
      if (hour === '09' || hour === '20') {
        isValidMinuteForHour = minute === '00';
      } else {
        isValidMinuteForHour = ['00', '10', '20', '30', '40', '50'].includes(minute ?? '');
      }

      if (hour && minute && validHours.includes(hour) && isValidMinuteForHour) {
        if (selectedHour !== hour) setSelectedHour(hour);
        if (selectedMinute !== minute) setSelectedMinute(minute);
      } else {
        // postData.targetTime이 유효하지 않으면 선택 초기화
        if (selectedHour !== '') setSelectedHour('');
        if (selectedMinute !== '') setSelectedMinute('');
      }
    } else {
      // postData.targetTime이 비어있으면 선택 초기화
      if (selectedHour !== '') setSelectedHour('');
      if (selectedMinute !== '') setSelectedMinute('');
    }
  }, [postData.targetTime]);

  // selectedHour가 변경될 때 availableMinutes 및 selectedMinute 업데이트
  useEffect(() => {
    if (selectedHour === '09' || selectedHour === '20') {
      setAvailableMinutes(['00']);
      if (selectedMinute !== '00') {
        setSelectedMinute('00'); // 09시 또는 20시 선택 시 분을 00분으로 강제
      }
    } else {
      setAvailableMinutes(['00', '10', '20', '30', '40', '50']);
      // 다른 시간으로 변경 시, 기존 선택된 분이 유효하지 않으면 초기화될 수 있도록 함
      // (예: 09:00 에서 07:xx 로 변경시 selectedMinute는 '00'으로 유지되지만, 만약 07:00이 아닌 다른 분을 원하면 사용자가 재선택)
      // 만약 이전에 09:xx 또는 20:xx 였다가 다른 시간으로 바뀌고, selectedMinute가 '00'이 아닌 경우, 
      // 사용자가 유효한 분을 다시 선택해야 함. 현재 로직 상 targetTime이 비워지므로 괜찮음.
    }
  }, [selectedHour]); // selectedMinute를 의존성 배열에서 제거하여 selectedHour 변경 시에만 실행

  // 단계별 컨텐츠 렌더링
  const renderStepContent = () => {
    // 제출 완료 화면
    if (isSubmitComplete) {
      return (
        <Box sx={{ 
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center', 
          justifyContent: 'center',
          height: '100%',
          py: 8
        }}>
          <CheckCircleIcon color="primary" fontSize="large" sx={{ fontSize: 72, mb: 3 }} />
          <Typography variant="h6" align="center" gutterBottom>
            작성 완료
          </Typography>
          <Typography variant="body2" align="center" color="text.secondary">
            MIO에 정상적으로 등록되었습니다!
          </Typography>
        </Box>
      );
    }

    switch (currentStep) {
      case 1:
        return (
          <>
            <StepIndicator>1 / 4</StepIndicator>
            <Typography variant="h6" sx={{ mb: 3, fontWeight: 'bold' }}>
              일정을 만들어보세요
            </Typography>
            
            <InputContainer>
              <TextField
                fullWidth
                placeholder="제목을 입력해주세요"
                value={postData.title}
                onChange={(e) => setPostData({ ...postData, title: e.target.value })}
                variant="outlined"
                sx={{ mb: 3 }}
              />
              
              <Box sx={{ mb: 2 }}>
                <Typography variant="body1" sx={{ mb: 1 }}>날짜</Typography>
                <TextField
                  fullWidth
                  type="date"
                  value={postData.targetDate}
                  onChange={(e) => setPostData({ ...postData, targetDate: e.target.value })}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <CalendarIcon color="primary" />
                      </InputAdornment>
                    ),
                    sx: {
                      cursor: 'pointer',
                      '& input::-webkit-calendar-picker-indicator': {
                        position: 'absolute',
                        width: '100%',
                        height: '100%',
                        opacity: 0,
                        cursor: 'pointer'
                      }
                    }
                  }}
                  sx={{
                    '& .MuiInputBase-root': {
                      borderRadius: 1,
                    },
                    '& input': {
                      cursor: 'pointer'
                    }
                  }}
                />
              </Box>
              
              <Box sx={{ mb: 3 }}>
                <Typography variant="body1" sx={{ mb: 1 }}>시간</Typography>
                <Grid container spacing={1} alignItems="center">
                  <Grid item xs={5}>
                    <FormControl fullWidth variant="outlined">
                      <InputLabel id="hour-select-label">시</InputLabel>
                      <Select
                        labelId="hour-select-label"
                        value={selectedHour}
                        label="시"
                        onChange={(e) => setSelectedHour(e.target.value as string)}
                      >
                        <MenuItem value="">
                          <Typography variant="body2" sx={{ fontStyle: 'italic' }}>선택</Typography>
                        </MenuItem>
                        {['07', '08', '09', '18', '19', '20'].map(h => (
                          <MenuItem key={h} value={h}>{h}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={1} sx={{ textAlign: 'center', lineHeight: 'normal' }}> {/* 중앙 정렬 및 수직 정렬 개선 */}
                      <Typography variant="h6">:</Typography> {/* 콜론 크기 및 스타일 조정 */}
                  </Grid>
                  <Grid item xs={5}>
                    <FormControl fullWidth variant="outlined">
                      <InputLabel id="minute-select-label">분</InputLabel>
                      <Select
                        labelId="minute-select-label"
                        value={selectedMinute}
                        label="분"
                        onChange={(e) => setSelectedMinute(e.target.value as string)}
                      >
                        <MenuItem value="">
                          <Typography variant="body2" sx={{ fontStyle: 'italic' }}>선택</Typography>
                        </MenuItem>
                        {availableMinutes.map(m => (
                          <MenuItem key={m} value={m}>{m}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                </Grid>
                {(!selectedHour || !selectedMinute) && (postData.title !== '' || postData.targetDate !== '') && (
                  <Typography color="error" sx={{ fontSize: '0.75rem', mt: 0.5 }}>
                    시간과 분을 모두 선택해주세요.
                  </Typography>
                )}
              </Box>
              
              <Box sx={{ mb: 3 }}>
                <Typography variant="body1" sx={{ mb: 1 }}>카풀 / 택시</Typography>
                <Grid container spacing={1}>
                  <Grid item xs={6}>
                    <SelectionButton 
                      fullWidth 
                      className={selectedCategory === '카풀' ? 'selected' : ''}
                      onClick={() => setSelectedCategory('카풀')}
                    >
                      카풀
                    </SelectionButton>
                  </Grid>
                  <Grid item xs={6}>
                    <SelectionButton 
                      fullWidth 
                      className={selectedCategory === '택시' ? 'selected' : ''}
                      onClick={() => setSelectedCategory('택시')}
                    >
                      택시
                    </SelectionButton>
                  </Grid>
                </Grid>
              </Box>
              
              <Box sx={{ mb: 3 }}>
                <Typography variant="body1" sx={{ mb: 1 }}>탑승인원</Typography>
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <CounterButton onClick={decreasePassengers}>
                    <RemoveIcon fontSize="small" />
                  </CounterButton>
                  <CounterDisplay>
                    {postData.numberOfPassengers}
                  </CounterDisplay>
                  <CounterButton onClick={increasePassengers}>
                    <AddIcon fontSize="small" />
                  </CounterButton>
                </Box>
              </Box>
              
              <Box>
                <Typography variant="body1" sx={{ mb: 1 }}>요금</Typography>
                <TextField
                  fullWidth
                  placeholder="0"
                  value={postData.cost || ''}
                  onChange={(e) => {
                    const value = parseInt(e.target.value);
                    if (!isNaN(value) || e.target.value === '') {
                      setPostData({
                        ...postData,
                        cost: e.target.value === '' ? 0 : value
                      });
                    }
                  }}
                  type="number"
                  InputProps={{
                    endAdornment: <InputAdornment position="end">원</InputAdornment>,
                  }}
                  variant="outlined"
                />
              </Box>
            </InputContainer>
          </>
        );
        
      case 2:
        return (
          <>
            <StepIndicator>2 / 4</StepIndicator>
            <Typography variant="h6" sx={{ mb: 3, fontWeight: 'bold' }}>
              어디에서 만날까요?
            </Typography>
            
            {!showMap ? (
              // 위치 검색 화면
              <>
                <Box sx={{ mb: 2, position: 'relative' }}>
                  <StyledInputBase
                    placeholder="장소를 입력해주세요"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    endAdornment={
                      <IconButton size="small">
                        <SearchIcon />
                      </IconButton>
                    }
                  />
                  
                  {isSearching && (
                    <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                      <CircularProgress size={24} />
                    </Box>
                  )}
                  
                  {searchResults.length > 0 && (
                    <SearchResultList>
                      {searchResults.map((result) => (
                        <LocationItem 
                          key={result.id} 
                          onClick={() => handleSelectLocation(result)}
                        >
                          <ListItemText
                            primary={
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <LocationIcon fontSize="small" color="action" />
                                <Typography variant="body1">{result.name}</Typography>
                              </Box>
                            }
                            secondary={result.address}
                            primaryTypographyProps={{
                              fontWeight: 500,
                              color: 'text.primary'
                            }}
                            secondaryTypographyProps={{
                              fontSize: '0.75rem'
                            }}
                          />
                        </LocationItem>
                      ))}
                    </SearchResultList>
                  )}
                  
                  {!isSearching && searchQuery && searchResults.length === 0 && (
                    <Box sx={{ mt: 2, textAlign: 'center' }}>
                      <Typography color="text.secondary">
                        검색 결과가 없습니다.
                      </Typography>
                    </Box>
                  )}
                </Box>
                
                {/* 최근 검색어 또는 추천 위치 */}
                {!searchQuery && (
                  <Box sx={{ mt: 4 }}>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                      최근 검색어
                    </Typography>
                    {recentSearchResults.length > 0 ? (
                      <List>
                        {recentSearchResults.slice(0, 3).map((result) => (
                          <LocationItem 
                            key={result.id} 
                            onClick={() => handleSelectLocation(result)}
                          >
                            <ListItemText
                              primary={
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                  <LocationIcon fontSize="small" color="action" />
                                  <Typography variant="body1">{result.name}</Typography>
                                </Box>
                              }
                              secondary={result.address}
                              primaryTypographyProps={{
                                fontWeight: 500,
                                color: 'text.primary'
                              }}
                              secondaryTypographyProps={{
                                fontSize: '0.75rem'
                              }}
                            />
                          </LocationItem>
                        ))}
                      </List>
                    ) : (
                      <Box sx={{ mt: 2, textAlign: 'center' }}>
                        <Typography color="text.secondary">
                          최근 검색 기록이 없습니다.
                        </Typography>
                      </Box>
                    )}
                  </Box>
                )}
              </>
            ) : (
              // 지도 위치 설정 화면
              <>
                {selectedLocation && (
                  <Box>
                    <Typography variant="body1" sx={{ mb: 1, fontWeight: 'medium' }}>
                      {selectedLocation.name}
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      {selectedLocation.address}
                    </Typography>
                    
                    <Paper elevation={1} sx={{ p: 0.5, mb: 2 }}>
                      <Typography variant="caption" sx={{ p: 1, display: 'block', color: 'text.secondary' }}>
                        핀을 드래그하여 정확한 위치를 지정할 수 있습니다.
                      </Typography>
                      <Box 
                        ref={mapRef} 
                        sx={{ 
                          width: '100%', 
                          height: '300px',
                          borderRadius: 1,
                          overflow: 'hidden'
                        }}
                      />
                    </Paper>
                    
                    <Box sx={{ display: 'flex', mt: 3, gap: 1 }}>
                      <Button
                        variant="outlined"
                        fullWidth
                        onClick={resetLocationSearch}
                      >
                        다시 검색
                      </Button>
                      <Button
                        variant="contained"
                        color="primary"
                        fullWidth
                        onClick={confirmLocation}
                      >
                        위치 확인
                      </Button>
                    </Box>
                  </Box>
                )}
              </>
            )}
          </>
        );
        
      case 3:
        return (
          <>
            <StepIndicator>3 / 4</StepIndicator>
            <Typography variant="h6" sx={{ mb: 3, fontWeight: 'bold' }}>
              상세 정보를 입력해주세요
            </Typography>
            
            <Box sx={{ mb: 3 }}>
              <Typography variant="subtitle1" sx={{ mb: 1 }}>등 / 하교</Typography>
              <Grid container spacing={1}>
                <Grid item xs={6}>
                  <SelectionButton 
                    fullWidth 
                    className={postData.verifyGoReturn ? 'selected' : ''}
                    onClick={() => setPostData({...postData, verifyGoReturn: true})}
                  >
                    등교
                  </SelectionButton>
                </Grid>
                <Grid item xs={6}>
                  <SelectionButton 
                    fullWidth 
                    className={!postData.verifyGoReturn ? 'selected' : ''}
                    onClick={() => setPostData({...postData, verifyGoReturn: false})}
                  >
                    하교
                  </SelectionButton>
                </Grid>
              </Grid>
            </Box>
            
            <Box sx={{ mb: 3 }}>
              <Typography variant="subtitle1" sx={{ mb: 1 }}>성별</Typography>
              <Grid container spacing={1}>
                <Grid item xs={6}>
                  <SelectionButton 
                    fullWidth 
                    className={!postData.gender ? 'selected' : ''}
                    onClick={() => setPostData({...postData, gender: false})}
                  >
                    남성
                  </SelectionButton>
                </Grid>
                <Grid item xs={6}>
                  <SelectionButton 
                    fullWidth 
                    className={postData.gender ? 'selected' : ''}
                    onClick={() => setPostData({...postData, gender: true})}
                  >
                    여성
                  </SelectionButton>
                </Grid>
              </Grid>
            </Box>
            
            <Box sx={{ mb: 3 }}>
              <Typography variant="subtitle1" sx={{ mb: 1 }}>흡연여부</Typography>
              <Grid container spacing={1}>
                <Grid item xs={6}>
                  <SelectionButton 
                    fullWidth 
                    className={!postData.verifySmoker ? 'selected' : ''}
                    onClick={() => setPostData({...postData, verifySmoker: false})}
                  >
                    O
                  </SelectionButton>
                </Grid>
                <Grid item xs={6}>
                  <SelectionButton 
                    fullWidth 
                    className={postData.verifySmoker ? 'selected' : ''}
                    onClick={() => setPostData({...postData, verifySmoker: true})}
                  >
                    X
                  </SelectionButton>
                </Grid>
              </Grid>
            </Box>
          </>
        );
        
      case 4:
        return (
          <>
            <StepIndicator>4 / 4</StepIndicator>
            <Typography variant="h6" sx={{ mb: 3, fontWeight: 'bold' }}>
              추가 내용을 작성해주세요 <Typography component="span" color="error" display="inline">*</Typography>
            </Typography>
            
            <TextField
              fullWidth
              multiline
              rows={5}
              placeholder="여러 사정 및 추가적인 안내사항을 입력해주세요"
              value={postData.content}
              onChange={(e) => setPostData({ ...postData, content: e.target.value })}
              variant="outlined"
              sx={{ mb: 3 }}
              required
              error={currentStep === 4 && !postData.content}
              helperText={currentStep === 4 && !postData.content ? "내용을 입력해주세요" : ""}
            />
          </>
        );
        
      default:
        return null;
    }
  };

  return (
    <Container maxWidth="sm" sx={{ height: '100vh', display: 'flex', flexDirection: 'column', p: 0 }}>
      <Paper elevation={0} sx={{ 
        display: 'flex', 
        flexDirection: 'column', 
        height: '100%',
        borderRadius: 0
      }}>
        {/* 헤더 */}
        <StepHeader>
          <IconButton edge="start" color="inherit" onClick={goToPrevStep} disabled={isSubmitComplete}>
            <CloseIcon />
          </IconButton>
          {currentStep !== 4 && !isSubmitComplete && (
            <Typography variant="subtitle1">
              {currentStep === 1 ? '글쓰기 / 제목, 날짜, 시간, 탑승인원' : 
                currentStep === 2 ? '글쓰기 / 픽업 위치 입력' : 
                currentStep === 3 ? '글쓰기 / 상세 정보 입력' :
                '글쓰기 / 추가 내용 작성'}
            </Typography>
          )}
          {isSubmitComplete && (
            <Typography variant="subtitle1">
              글쓰기 완료
            </Typography>
          )}
          <Box width={24} /> {/* 빈 공간 균형을 위해 */}
        </StepHeader>
        
        {/* 단계별 콘텐츠 */}
        <StepContent>
          {renderStepContent()}
        </StepContent>
        
        {/* 하단 버튼 영역 */}
        {!isSubmitComplete && !(currentStep === 2 && showMap) && (
          <StepFooter>
            {currentStep < 4 ? (
              <>
                {currentStep > 1 && (
                  <Button
                    variant="outlined"
                    sx={{ mr: 1, flex: 1 }}
                    onClick={goToPrevStep}
                  >
                    이전
                  </Button>
                )}
                <Button
                  fullWidth
                  variant="contained"
                  color="primary"
                  onClick={goToNextStep}
                  disabled={!isStepValid(currentStep)}
                  sx={{ flex: currentStep > 1 ? 2 : 1 }}
                >
                  다음
                </Button>
              </>
            ) : (
              <>
                <Button
                  variant="outlined"
                  sx={{ mr: 1, flex: 1 }}
                  onClick={goToPrevStep}
                >
                  이전
                </Button>
                <Button
                  fullWidth
                  variant="contained"
                  color="primary"
                  onClick={handleSubmit}
                  disabled={isSubmitting}
                  sx={{ flex: 2 }}
                >
                  {isSubmitting ? (
                    <CircularProgress size={24} color="inherit" />
                  ) : (
                    '등록'
                  )}
                </Button>
              </>
            )}
          </StepFooter>
        )}
        
        {isSubmitComplete && (
          <StepFooter>
            <Button
              fullWidth
              variant="contained"
              color="primary"
              onClick={() => navigate('/')}
            >
              네, 알았어요!
            </Button>
          </StepFooter>
        )}
      </Paper>
    </Container>
  );
};

export default PostCreatePage; 