import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  Paper,
  Typography,
  TextField,
  Button,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormHelperText,
  CircularProgress,
  Snackbar,
  Alert,
  Divider,
  SelectChangeEvent,
  List,
  ListItem,
  ListItemText,
  Radio,
  RadioGroup,
  FormControlLabel,
  InputAdornment,
  Autocomplete,
  ClickAwayListener,
} from '@mui/material';
import { ArrowBack, Search, Close } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { encryptText, decryptText } from '../utils/crypto'; // 암복호화 유틸리티 임포트

// API 기본 URL
// const API_BASE_URL = 'https://mioserver.o-r.kr/'; // 환경 변수로 대체

// 한국 주요 은행 목록
const BANKS = [
  { code: 'KB', name: 'KB국민은행' },
  { code: 'SHINHAN', name: '신한은행' },
  { code: 'WOORI', name: '우리은행' },
  { code: 'HANA', name: '하나은행' },
  { code: 'IBK', name: 'IBK기업은행' },
  { code: 'NONGHYUP', name: '농협은행' },
  { code: 'KOOKMIN', name: '새마을금고' },
  { code: 'POST', name: '우체국' },
  { code: 'TOSS', name: '토스뱅크' },
  { code: 'KAKAO', name: '카카오뱅크' },
  { code: 'KBANK', name: '케이뱅크' },
  { code: 'SC', name: 'SC제일은행' },
  { code: 'DAEGU', name: '대구은행' },
  { code: 'BUSAN', name: '부산은행' },
  { code: 'GWANGJU', name: '광주은행' },
  { code: 'JEJU', name: '제주은행' },
  { code: 'JEONBUK', name: '전북은행' },
  { code: 'KYONGNAM', name: '경남은행' },
  { code: 'CITI', name: '한국씨티은행' }
];

// 추가 정보 폼 타입 (백엔드 DTO와 동일하게 구성)
interface AdditionalUserPatchDto {
  gender?: boolean;          // false: 남성, true: 여성
  verifySmoker?: boolean;    // false: 비흡연, true: 흡연
  
  // 암호화된 값과 IV를 쉼표로 구분하여 합친 문자열을 받는 필드
  accountNumber?: string; 
  activityLocation?: string;
}

// 내부 상태 관리를 위한 확장된 폼 타입
interface ExtendedFormData {
  gender?: boolean;
  verifySmoker?: boolean;
  accountNumber: string;    // 복호화된 값 또는 사용자 입력 값
  activityLocation: string; // 복호화된 값 또는 사용자 입력 값
  selectedBank?: string;
  accountNumberOnly?: string;
}

// 검색된 지역 정보 타입
interface LocationResult {
  fullName: string;
  city: string;
  district: string;
  dong: string;
}

// 샘플 지역 데이터 (실제로는 API에서 가져오는 것이 좋습니다)
const SAMPLE_LOCATIONS: LocationResult[] = [
  { fullName: '서울특별시 노원구 하계동', city: '서울특별시', district: '노원구', dong: '하계동' },
  { fullName: '서울특별시 노원구 중계동', city: '서울특별시', district: '노원구', dong: '중계동' },
  { fullName: '서울특별시 노원구 월계동', city: '서울특별시', district: '노원구', dong: '월계동' },
  { fullName: '서울특별시 노원구 공릉동', city: '서울특별시', district: '노원구', dong: '공릉동' },
  { fullName: '서울특별시 중구 을지로동', city: '서울특별시', district: '중구', dong: '을지로동' },
  { fullName: '서울특별시 강남구 역삼동', city: '서울특별시', district: '강남구', dong: '역삼동' },
  { fullName: '서울특별시 강남구 삼성동', city: '서울특별시', district: '강남구', dong: '삼성동' },
  { fullName: '경기도 성남시 분당구 판교동', city: '경기도', district: '성남시 분당구', dong: '판교동' },
  { fullName: '경기도 수원시 영통구 영통동', city: '경기도', district: '수원시 영통구', dong: '영통동' },
];

const ProfileEditPage: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [saveLoading, setSaveLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [formData, setFormData] = useState<ExtendedFormData>({
    gender: undefined,
    verifySmoker: undefined,
    accountNumber: '',
    activityLocation: '',
    selectedBank: '',
    accountNumberOnly: ''
  });

  // 지역 검색을 위한 상태
  const [locationSearchQuery, setLocationSearchQuery] = useState('');
  const [locationSearchResults, setLocationSearchResults] = useState<LocationResult[]>([]);
  const [locationSearchOpen, setLocationSearchOpen] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState<LocationResult | null>(null);

  // 사용자 정보 - 로컬 스토리지에서 이메일 및 ID 가져오기
  const userEmail = localStorage.getItem('userEmail') || '';
  const userId = localStorage.getItem('userId') || '1'; // 저장용 아이디

  // 계좌번호 조합하기
  const combineAccountInfo = (): string => {
    if (!formData.selectedBank || !formData.accountNumberOnly) return '';
    const bankName = BANKS.find(bank => bank.code === formData.selectedBank)?.name || '';
    return `${bankName} ${formData.accountNumberOnly}`;
  };

  // DTO 변환 함수: 백엔드에 전송할 데이터 구조로 변환
  const prepareDataForSubmission = async (): Promise<AdditionalUserPatchDto> => {
    // 계좌번호 조합
    const combinedAccountNumber = combineAccountInfo();
    
    let finalAccountNumberPayload: string | undefined = undefined;
    if (combinedAccountNumber) {
      const encryptedAccount = await encryptText(combinedAccountNumber);
      if (encryptedAccount.cipherText && encryptedAccount.iv) {
        finalAccountNumberPayload = `${encryptedAccount.cipherText},${encryptedAccount.iv}`; // 쉼표로 구분
      }
    }

    let finalActivityLocationPayload: string | undefined = undefined;
    if (formData.activityLocation) {
      const encryptedLocation = await encryptText(formData.activityLocation);
      if (encryptedLocation.cipherText && encryptedLocation.iv) {
        finalActivityLocationPayload = `${encryptedLocation.cipherText},${encryptedLocation.iv}`; // 쉼표로 구분
      }
    }
    
    return {
      gender: formData.gender,
      verifySmoker: formData.verifySmoker,
      accountNumber: finalAccountNumberPayload,
      activityLocation: finalActivityLocationPayload,
    };
  };

  // 사용자 정보 불러오기 - 이메일로 조회
  const fetchUserInfo = async () => {
    if (!userEmail) {
      setError('사용자 이메일 정보가 없습니다. 다시 로그인해주세요.');
      return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('userToken');
      
      const response = await axios.get(`${process.env.REACT_APP_API_BASE_URL}/user/email/${encodeURIComponent(userEmail)}`, {
        headers: {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        }
      });

      const userData = response.data; // 이제 userData.accountNumber와 userData.activityLocation이 "encrypted,IV" 형태
      
      let decryptedAccountNumber = '';
      if (userData.accountNumber) {
        const parts = userData.accountNumber.split(',');
        if (parts.length === 2) {
          const cipherText = parts[0];
          const iv = parts[1];
          decryptedAccountNumber = await decryptText(cipherText, iv);
        } else {
          console.warn('Received account number in unexpected format (expected "encrypted,IV")_:', userData.accountNumber);
          // 암호화되지 않은 값으로 간주하거나, 빈 값으로 처리. 또는 오류.
          // decryptedAccountNumber = userData.accountNumber; // 만약 암호화 안된 값일 경우
        }
      }

      let decryptedActivityLocation = '';
      if (userData.activityLocation) {
        const parts = userData.activityLocation.split(',');
        if (parts.length === 2) {
          const cipherText = parts[0];
          const iv = parts[1];
          decryptedActivityLocation = await decryptText(cipherText, iv);
        } else {
          console.warn('Received activity location in unexpected format (expected "encrypted,IV")_:', userData.activityLocation);
        }
      }
      
      let selectedBank = '';
      let accountNumberOnly = '';
      
      if (decryptedAccountNumber) { // 복호화된 계좌번호 사용
        // "은행명 계좌번호" 형식에서 분리
        const parts = decryptedAccountNumber.split(' ');
        if (parts.length >= 2) {
          const bankName = parts[0];
          accountNumberOnly = parts.slice(1).join(' ');
          
          // 은행명으로 은행 코드 찾기
          const bankFound = BANKS.find(bank => bank.name === bankName);
          selectedBank = bankFound?.code || '';
        }
      }
      
      setFormData({
        gender: userData.gender,
        verifySmoker: userData.verifySmoker,
        accountNumber: decryptedAccountNumber, // 복호화된 값으로 설정
        activityLocation: decryptedActivityLocation, // 복호화된 값으로 설정
        selectedBank,
        accountNumberOnly
      });

      // 저장된 위치가 있으면 해당 위치로 selectedLocation 설정
      if (decryptedActivityLocation) { // 복호화된 활동 지역 사용
        const matchedLocation = SAMPLE_LOCATIONS.find(loc => loc.fullName === decryptedActivityLocation);
        if (matchedLocation) {
          setSelectedLocation(matchedLocation);
        }
      }
      
      // 사용자 ID가 없으면 ID도 저장해두기
      if (!localStorage.getItem('userId') && userData.id) {
        localStorage.setItem('userId', String(userData.id));
      }
      
    } catch (err) {
      console.error('사용자 정보를 불러오는데 실패했습니다:', err);
      setError('사용자 정보를 불러오지 못했습니다. 다시 로그인하거나 나중에 다시 시도해주세요.');
    } finally {
      setLoading(false);
    }
  };

  // 사용자 정보 저장하기
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaveLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem('userToken');
      
      // 백엔드 DTO 형식에 맞게 데이터 변환 (await 추가)
      const dataToSend = await prepareDataForSubmission(); 
      
      await axios.patch(
        `${process.env.REACT_APP_API_BASE_URL}/user/${userId}`,
        dataToSend,
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );

      setSuccess(true);
      setTimeout(() => {
        navigate('/profile');
      }, 1500);
    } catch (err) {
      console.error('프로필 업데이트 실패:', err);
      setError('프로필 정보를 업데이트하지 못했습니다.');
    } finally {
      setSaveLoading(false);
    }
  };

  // 텍스트 필드 변경 핸들러
  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // 셀렉트 변경 핸들러
  const handleSelectChange = (e: SelectChangeEvent) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // 라디오 버튼 변경 핸들러 (Boolean 타입)
  const handleRadioChange = (e: React.ChangeEvent<HTMLInputElement>, name: string) => {
    const value = e.target.value === 'true';
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // 지역 검색어 변경 핸들러
  const handleLocationSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const query = e.target.value;
    setLocationSearchQuery(query);

    if (query.trim().length > 0) {
      // 실제로는 API로 검색하는 것이 좋습니다
      const filteredResults = SAMPLE_LOCATIONS.filter(
        location => 
          location.fullName.toLowerCase().includes(query.toLowerCase()) ||
          location.dong.toLowerCase().includes(query.toLowerCase())
      );
      setLocationSearchResults(filteredResults);
      setLocationSearchOpen(true);
    } else {
      setLocationSearchResults([]);
      setLocationSearchOpen(false);
    }
  };

  // 지역 선택 핸들러
  const handleLocationSelect = (location: LocationResult) => {
    // 주소 형식 통일화
    let simplifiedAddress = location.fullName;
    
    // 특별시, 광역시 등의 명칭을 간단히 변경
    simplifiedAddress = simplifiedAddress
      .replace('서울특별시', '서울')
      .replace('부산광역시', '부산')
      .replace('대구광역시', '대구')
      .replace('인천광역시', '인천')
      .replace('광주광역시', '광주')
      .replace('대전광역시', '대전')
      .replace('울산광역시', '울산')
      .replace('세종특별자치시', '세종')
      .replace('제주특별자치도', '제주');

    setSelectedLocation(location);
    setLocationSearchQuery(''); // 검색창 비우기
    setLocationSearchOpen(false);
    setFormData(prev => ({
      ...prev,
      activityLocation: simplifiedAddress
    }));
  };

  // 선택된 지역 지우기
  const clearSelectedLocation = () => {
    setSelectedLocation(null);
    setFormData(prev => ({
      ...prev,
      activityLocation: ''
    }));
  };

  // 컴포넌트 마운트시 사용자 정보 불러오기
  useEffect(() => {
    fetchUserInfo();
  }, []);

  // 로그인 정보가 없을 경우 표시할 화면
  if (!userEmail && !loading) {
    return (
      <Container maxWidth="sm" sx={{ pt: 2, pb: 8 }}>
        <Paper elevation={0} sx={{ borderRadius: '12px', p: 3, textAlign: 'center' }}>
          <Typography variant="h6" gutterBottom>
            로그인이 필요합니다
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
            프로필을 수정하려면 먼저 로그인해주세요.
          </Typography>
          <Button 
            variant="contained" 
            onClick={() => navigate('/login')}
          >
            로그인 하기
          </Button>
        </Paper>
      </Container>
    );
  }

  return (
    <Container maxWidth="sm" sx={{ pt: 2, pb: 8 }}>
      <Paper elevation={0} sx={{ borderRadius: '12px', mb: 2 }}>
        {/* 헤더 */}
        <Box sx={{ 
          p: 2, 
          display: 'flex', 
          alignItems: 'center',
          borderBottom: '1px solid',
          borderBottomColor: 'divider'
        }}>
          <IconButton 
            edge="start" 
            color="inherit" 
            onClick={() => navigate('/profile')} 
            sx={{ mr: 1 }}
          >
            <ArrowBack />
          </IconButton>
          <Typography variant="h6" component="div" sx={{ fontWeight: 'bold' }}>
            프로필 편집
          </Typography>
        </Box>

        {/* 로딩 표시 */}
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
            <CircularProgress />
          </Box>
        ) : (
          <Box component="form" onSubmit={handleSubmit} sx={{ p: 3 }}>
            {/* 개인 정보 섹션 */}
            <Typography variant="h6" gutterBottom sx={{ mb: 2 }}>
              개인 정보
            </Typography>
            
            {/* 성별 선택 - 라디오 버튼으로 변경 */}
            <FormControl fullWidth margin="normal">
              <Typography variant="body1" color="text.primary" gutterBottom>
                성별
              </Typography>
              <RadioGroup
                row
                value={formData.gender === undefined ? '' : String(formData.gender)}
                onChange={(e) => handleRadioChange(e, 'gender')}
              >
                <FormControlLabel value="false" control={<Radio />} label="남성" />
                <FormControlLabel value="true" control={<Radio />} label="여성" />
              </RadioGroup>
            </FormControl>
            
            {/* 흡연 여부 */}
            <FormControl fullWidth margin="normal">
              <Typography variant="body1" color="text.primary" gutterBottom>
                흡연 여부
              </Typography>
              <RadioGroup
                row
                value={formData.verifySmoker === undefined ? '' : String(formData.verifySmoker)}
                onChange={(e) => handleRadioChange(e, 'verifySmoker')}
              >
                <FormControlLabel value="false" control={<Radio />} label="X (비흡연)" />
                <FormControlLabel value="true" control={<Radio />} label="O (흡연)" />
              </RadioGroup>
            </FormControl>
            
            {/* 활동 지역 */}
            <FormControl fullWidth margin="normal">
              <Typography variant="body1" color="text.primary" gutterBottom>
                활동 지역
              </Typography>
              
              {selectedLocation ? (
                <Box 
                  sx={{ 
                    display: 'flex', 
                    alignItems: 'center', 
                    p: 2, 
                    border: '1px solid', 
                    borderColor: 'divider',
                    borderRadius: 1
                  }}
                >
                  <Box sx={{ flex: 1 }}>
                    <Typography variant="body1">{selectedLocation.fullName}</Typography>
                  </Box>
                  <IconButton size="small" onClick={clearSelectedLocation}>
                    <Close fontSize="small" />
                  </IconButton>
                </Box>
              ) : (
                <ClickAwayListener onClickAway={() => setLocationSearchOpen(false)}>
                  <Box sx={{ position: 'relative', width: '100%' }}>
                    <TextField
                      fullWidth
                      placeholder="동 이름을 입력해주세요 (예: 하계동)"
                      value={locationSearchQuery}
                      onChange={handleLocationSearchChange}
                      InputProps={{
                        startAdornment: (
                          <InputAdornment position="start">
                            <Search />
                          </InputAdornment>
                        ),
                      }}
                      onClick={() => {
                        if (locationSearchQuery.trim().length > 0) {
                          setLocationSearchOpen(true);
                        }
                      }}
                    />
                    {locationSearchOpen && locationSearchResults.length > 0 && (
                      <Paper 
                        elevation={3}
                        sx={{ 
                          position: 'absolute', 
                          top: '100%', 
                          left: 0, 
                          right: 0, 
                          mt: 0.5,
                          maxHeight: 200,
                          overflow: 'auto',
                          zIndex: 1000
                        }}
                      >
                        <List dense>
                          {locationSearchResults.map((location, index) => (
                            <ListItem 
                              button 
                              key={index} 
                              onClick={() => handleLocationSelect(location)}
                            >
                              <ListItemText 
                                primary={location.fullName} 
                              />
                            </ListItem>
                          ))}
                        </List>
                      </Paper>
                    )}
                  </Box>
                </ClickAwayListener>
              )}
            </FormControl>

            <Divider sx={{ my: 3 }} />
            
            {/* 계좌 정보 섹션 */}
            <Typography variant="h6" gutterBottom sx={{ mb: 2 }}>
              계좌 정보
            </Typography>
            
            {/* 은행 선택 드롭다운 */}
            <FormControl fullWidth margin="normal">
              <InputLabel>은행 선택</InputLabel>
              <Select
                name="selectedBank"
                value={formData.selectedBank || ''}
                label="은행 선택"
                onChange={handleSelectChange}
              >
                {BANKS.map((bank) => (
                  <MenuItem key={bank.code} value={bank.code}>
                    {bank.name}
                  </MenuItem>
                ))}
              </Select>
              <FormHelperText>계좌 정보는 "은행명과 계좌번호" 형식으로 저장됩니다</FormHelperText>
            </FormControl>
            
            {/* 계좌번호 입력 */}
            <Box sx={{ mt: 2 }}>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                계좌번호
              </Typography>
              <TextField
                fullWidth
                name="accountNumberOnly"
                value={formData.accountNumberOnly || ''}
                onChange={handleTextChange}
                placeholder="숫자만 입력하세요 (예: 11002233444566)"
                InputProps={{
                  startAdornment: formData.selectedBank && (
                    <InputAdornment position="start">
                      {BANKS.find(bank => bank.code === formData.selectedBank)?.name || ''}
                    </InputAdornment>
                  ),
                }}
                helperText="하이픈(-) 없이 숫자만 입력해주세요"
              />
            </Box>
            
            {/* 제출 버튼 */}
            <Box sx={{ mt: 4 }}>
              <Button
                type="submit"
                variant="contained"
                fullWidth
                disabled={saveLoading}
                startIcon={saveLoading ? <CircularProgress size={24} /> : null}
              >
                {saveLoading ? '저장 중...' : '저장'}
              </Button>
            </Box>
          </Box>
        )}
      </Paper>
      
      {/* 알림 메시지 */}
      <Snackbar 
        open={success} 
        autoHideDuration={3000} 
        onClose={() => setSuccess(false)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert severity="success" sx={{ width: '100%' }}>
          프로필이 성공적으로 업데이트되었습니다.
        </Alert>
      </Snackbar>
      
      <Snackbar 
        open={!!error} 
        autoHideDuration={3000} 
        onClose={() => setError(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert severity="error" sx={{ width: '100%' }}>
          {error}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default ProfileEditPage; 