import React from 'react';
import { 
  Box, 
  Typography, 
  Paper, 
  useTheme,
  ListItem
} from '@mui/material';
import { Person, DirectionsCar, Place, LocalOffer, Group, CalendarToday } from '@mui/icons-material';
import { motion } from 'framer-motion';
import { UiTimelineEvent } from '../types/post';

interface TimelineCardProps {
  event: UiTimelineEvent;
  onClick?: (postId: number) => void;
  showCategoryName?: boolean;
  showPrice?: boolean;
  isMobile?: boolean;
  sx?: React.CSSProperties;
}

/**
 * Timeline에서 사용하는 카드 컴포넌트
 * 프로필 페이지와 동일한 디자인의 카드 컴포넌트입니다.
 */
const TimelineCard: React.FC<TimelineCardProps> = ({ 
  event, 
  onClick,
  showCategoryName = false,
  showPrice = true,
  isMobile,
  sx
}) => {
  const theme = useTheme();
  
  // 테마 색상
  const primaryColor = theme.palette.primary.main;
  const iconColor = theme.palette.grey[500];
  
  // 반응형 스타일 값 계산
  const styles = {
    iconSize: isMobile ? '16px' : '20px',
    fontSize: {
      title: isMobile ? '14px' : '16px',
      body: isMobile ? '12px' : '14px',
    },
    spacing: {
      icon: isMobile ? 0.8 : 1,
      section: isMobile ? 0.8 : 1.5,
      contentPadding: isMobile ? 1.5 : 2,
    },
    sidebarWidth: isMobile ? '50px' : '60px',
    contentMargin: isMobile ? '55px' : '70px',
  };
  
  // 클릭 핸들러
  const handleClick = () => {
    if (onClick) {
      onClick(event.postId);
    }
  };

  return (
    <ListItem 
      button
      alignItems="flex-start"
      onClick={handleClick}
      sx={{ 
        p: 0, 
        position: 'relative',
        borderBottom: `1px solid ${theme.palette.divider}`,
        '&:last-child': {
          borderBottom: 'none',
        },
        borderRadius: theme.shape.borderRadius * 3,
        backgroundColor: theme.palette.background.paper,
        boxShadow: '0px 2px 8px rgba(0, 0, 0, 0.08)',
        mb: 2,
        overflow: 'hidden',
        ...sx
      }}
    >
      {/* 왼쪽 파란색 선과 아이콘 */}
      <Box sx={{ 
        position: 'absolute',
        left: 0,
        top: 0,
        bottom: 0,
        width: styles.sidebarWidth,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
      }}>
        {/* 차 아이콘 */}
        <Box sx={{ 
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          mt: 2,
          position: 'relative',
          zIndex: 2
        }}>
          <DirectionsCar sx={{ color: primaryColor, fontSize: styles.iconSize }} />
        </Box>
        
        {/* 세로선 */}
        <Box sx={{ 
          width: '2px', 
          bgcolor: primaryColor, 
          position: 'absolute',
          top: theme.spacing(4.375), // 35px를 테마 스페이싱으로 변환
          bottom: theme.spacing(2.25), // 18px를 테마 스페이싱으로 변환
          zIndex: 1
        }} />
        
        {/* 동그라미 (선 끝에) */}
        <Box sx={{
          position: 'absolute',
          bottom: theme.spacing(2.25), // 18px를 테마 스페이싱으로 변환
          width: '6px',
          height: '6px',
          borderRadius: '50%',
          bgcolor: primaryColor,
          zIndex: 2
        }} />
      </Box>

      {/* 컨텐츠 */}
      <Box sx={{ 
        ml: styles.contentMargin, 
        py: styles.spacing.contentPadding,
        pr: theme.spacing(3),
        width: `calc(100% - ${styles.contentMargin})`,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center'
      }}>
        {/* 제목 */}
        <Typography 
          variant="body1" 
          fontWeight="bold" 
          sx={{ 
            mb: styles.spacing.section, 
            fontSize: styles.fontSize.title,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
          }}
        >
          {event.title}
        </Typography>

        {/* 날짜/시간 */}
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          mb: styles.spacing.section,
        }}>
          <CalendarToday sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
          <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
            {event.time}
          </Typography>
        </Box>

        {/* 장소 */}
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          mb: styles.spacing.section,
        }}>
          <Place sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
          <Typography 
            variant="body2" 
            color="text.secondary" 
            sx={{ 
              fontSize: styles.fontSize.body,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 1,
              WebkitBoxOrient: 'vertical',
            }}
          >
            {event.startLocation}
            {event.endLocation ? ` → ${event.endLocation}` : ''}
          </Typography>
        </Box>
        
        {/* 가격 정보 - showPrice가 true일 때만 표시 */}
        {showPrice && (
          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center',
            mb: styles.spacing.section,
          }}>
            <LocalOffer sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
            <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
              {event.price}
            </Typography>
          </Box>
        )}

        {/* 인원 */}
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          ...(showCategoryName ? { mb: styles.spacing.section } : {})
        }}>
          <Person sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
          <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
            {event.participants}
          </Typography>
        </Box>
        
        {/* 카테고리 이름 - showCategoryName이 true일 때만 표시 */}
        {showCategoryName && (
          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center',
          }}>
            <DirectionsCar sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
            <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
              {event.categoryName}
            </Typography>
          </Box>
        )}
      </Box>
    </ListItem>
  );
};

export default TimelineCard; 