interface CommentNodeProps {
  comment: CommentDto;
  level: number;
  onReply: (commentId: number) => void;
}

const CommentNode: React.FC<CommentNodeProps> = ({ comment, level, onReply }) => {
  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
  const open = Boolean(anchorEl);

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };

  const defaultUserForComment: UserDto = {
    id: 0,
    nickname: '익명',
    studentId: '-', // 기본 학번 값
    profileImageUrl: undefined,
  };
  const commentUser = comment.user || defaultUserForComment;

  return (
    <CommentNodeWrapper level={level}>
      <ListItem alignItems="flex-start" sx={{ px: 0, py: 1 }} disableGutters>
        <ListItemAvatar sx={{ minWidth: '40px', mt: 0.5 }}>
          <Avatar 
            src={commentUser.profileImageUrl} 
            alt={commentUser.nickname}
            sx={{ width: 32, height: 32}}
          >
              {commentUser.nickname?.[0]}
          </Avatar>
        </ListItemAvatar>
        <ListItemText
          disableTypography
          primary={<Typography variant="subtitle2" sx={{ fontWeight: 500, color: 'text.secondary', fontSize: '0.875rem' }}>{commentUser.studentId || '학번 없음'}</Typography>}
          secondary={
            <Box>
              <Typography
                component="p" // div 대신 p로 변경하여 의미 부여
                variant="body1" // 좀 더 큰 폰트
                color="text.primary"
                sx={{ whiteSpace: 'pre-wrap', my: 0.5, fontSize: '0.9375rem' }} // 본문 스타일
              >
                {comment.content}
              </Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.75rem' }}>
                  {dayjs(comment.createDate).fromNow()}
                </Typography>
                {/* 답글 달기 버튼 추가 - 최대 중첩 레벨 제한 (선택 사항) */}
                {level < 2 && (
                  <Button 
                    size="small" 
                    sx={{ 
                      minWidth: 'auto', 
                      padding: '0 4px', 
                      fontSize: '0.75rem', 
                      color: 'text.secondary',
                      '&:hover': { backgroundColor: 'transparent', textDecoration: 'underline' } 
                    }}
                    onClick={() => onReply(comment.commentId)}
                    startIcon={<Reply sx={{ fontSize: '0.875rem' }} />}
                  >
                    답글
                  </Button>
                )}
              </Box>
            </Box>
          }
        />
        <IconButton 
          aria-label="settings"
          onClick={handleClick}
          size="small"
          sx={{ position: 'absolute', top: 8, right: 0, color: 'text.disabled' }}
        >
          <MoreVert fontSize="small" />
        </IconButton>
        <Menu
          anchorEl={anchorEl}
          open={open}
          onClose={handleClose}
        >
          <MenuItem onClick={handleClose}>수정</MenuItem>
          <MenuItem onClick={handleClose}>삭제</MenuItem>
        </Menu>
      </ListItem>
      {comment.childComments && comment.childComments.length > 0 && (
        <List dense disablePadding sx={{ pl: 2 }}>
          {comment.childComments.map(child => (
            <CommentNode key={child.commentId} comment={child} level={level + 1} onReply={onReply} />
          ))}
        </List>
      )}
    </CommentNodeWrapper>
  );
};

// 북마크 DTO 인터페이스 추가
interface BookMarkDto {
  id: number;
  userId: number;
  postId: number;
  status: boolean;
}

interface BookmarkAddDto {
  addAndRemove: string;
}

// 참여(신청) 관련 인터페이스 추가
interface ParticipateCreateRequestDto {
  content: string;
  gender: boolean;
  verifySmoker: boolean;
  verifyGoReturn: boolean;
}

interface ParticipateDto {
  participantId: number;
  postId: number;
  userId: number;
  postUserId: number;
  content: string;
  approvalOrReject: string; // "APPROVAL" | "REJECT" | "WAITING" 등
  driverMannerFinish: boolean;
  passengerMannerFinish: boolean;
  verifyFinish: boolean;
  isDeleteYN: string;
}

interface ParticipateMsgDto {
  msg: string;
}

// 중요한 디버그 로그 추가 함수
const debugLog = (message: string, data?: any) => {
  console.log(`[PostDetailPage] ${message}`, data || '');
};

const PostDetailPage: React.FC = () => {
  const { postId } = useParams<{ postId: string }>();
  const navigate = useNavigate();
  const [post, setPost] = useState<PostDto | null>(null);
  const [loadingPost, setLoadingPost] = useState(true);
  const [postError, setPostError] = useState(false);

  const [comments, setComments] = useState<CommentDto[]>([]);
  const [loadingComments, setLoadingComments] = useState(false);
  const [commentsError, setCommentsError] = useState(false);

  const [newComment, setNewComment] = useState('');
  const [isSubmittingComment, setIsSubmittingComment] = useState(false);
  const [replyingToCommentId, setReplyingToCommentId] = useState<number | null>(null);
  const [replyingToCommentInfo, setReplyingToCommentInfo] = useState<{ id: number, content: string } | null>(null);
  
  // 북마크 상태 관리
  const [isBookmarked, setIsBookmarked] = useState<boolean>(false);
  const [loadingBookmark, setLoadingBookmark] = useState<boolean>(false);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthor, setIsAuthor] = useState<boolean>(false);
  
  // 참여(신청) 상태 관리
  const [isParticipated, setIsParticipated] = useState<boolean>(false);
  const [loadingParticipate, setLoadingParticipate] = useState<boolean>(false);
  const [participateDialogOpen, setParticipateDialogOpen] = useState<boolean>(false);
  const [participateContent, setParticipateContent] = useState<string>('');
  
  // 신청서 상태 관리를 위한 상태 변수들
  const [participateStep, setParticipateStep] = useState<number>(1); // 현재 단계 (1, 2, 3)
  const [participateData, setParticipateData] = useState<ParticipateCreateRequestDto>({
    content: '',
    gender: false, // 기본값: 남성
    verifySmoker: false, // 기본값: 비흡연
    verifyGoReturn: true, // 기본값: 등교
  });
  
  const commentInputRef = useRef<HTMLInputElement>(null);
  const participateContentRef = useRef<HTMLInputElement>(null);

  const [menuAnchorEl, setMenuAnchorEl] = useState<null | HTMLElement>(null);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);

  // 현재 로그인한 사용자 정보 가져오기
  useEffect(() => {
    const getUserFromStorage = () => {
      // 로컬스토리지에 'userInfo'가 없으므로 별도로 저장된 사용자 정보를 조합해서 사용
      const userToken = localStorage.getItem('userToken');
      const userName = localStorage.getItem('userName');
      const userEmail = localStorage.getItem('userEmail');
      const userId = localStorage.getItem('userId'); // 추가: 저장된 사용자 ID
      
      debugLog('저장된 토큰 정보:', {
        userToken: userToken ? '토큰 있음' : '토큰 없음',
        userName,
        userEmail,
        userId
      });
      
      // JWT 토큰 파싱 함수
      function parseJwt(token) {
        try {
          const base64Url = token.split('.')[1];
          const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
          const jsonPayload = decodeURIComponent(
            atob(base64)
              .split('')
              .map(function(c) {
                return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
              })
              .join('')
          );
          return JSON.parse(jsonPayload);
        } catch (e) {
          console.error("Error parsing JWT:", e);
          return null;
        }
      }
      
      if (userToken) {
        try {
          // JWT에서 사용자 정보 추출
          const payload = parseJwt(userToken);
          debugLog('JWT에서 추출한 정보:', payload);
          
          // 백엔드 JWT 구조 확인
          if (payload) {
            // JWT에서 가져온 정보로 사용자 객체 생성
            const userInfo = {
              id: userId ? Number(userId) : (payload.id || payload.userId || payload.sub), // ID 추출 로직 개선
              email: userEmail || payload.email,
              name: userName || payload.name
            };
            
            debugLog('현재 사용자 정보 설정됨:', userInfo);
            setCurrentUser(userInfo);
            
            // ID가 없거나 0 또는 NaN인 경우 경고 표시
            if (!userInfo.id || userInfo.id === 0 || isNaN(userInfo.id)) {
              console.warn('사용자 ID가 없거나 유효하지 않습니다:', userInfo);
            }
          } else {
            console.warn('JWT에서 사용자 정보를 추출할 수 없습니다.');
            // 로컬스토리지에서 직접 ID를 가져오는 시도
            const localUser = {
              id: userId ? Number(userId) : null,
              email: userEmail || null,
              name: userName || '사용자'
            };
            
            // ID 확인
            if (!localUser.id) {
              console.warn('로컬스토리지에서 사용자 ID를 찾을 수 없습니다.');
            }
            
            setCurrentUser(localUser);
            debugLog('로컬스토리지 기반 사용자 정보 설정:', localUser);
          }
        } catch (e) {
          console.error("Error parsing JWT or creating user info:", e);
          // 로컬스토리지에서 직접 ID를 가져오는 백업 로직
          const localUser = {
            id: userId ? Number(userId) : null,
            email: userEmail || null,
            name: userName || '사용자'
          };
          setCurrentUser(localUser);
          debugLog('에러 발생 후 로컬스토리지 기반 사용자 정보 설정:', localUser);
        }
      } else {
        // 토큰은 없지만 로컬스토리지에 ID가 있는 경우
        if (userId || userEmail) {
          const localUser = {
            id: userId ? Number(userId) : null,
            email: userEmail || null,
            name: userName || '사용자'
          };
          setCurrentUser(localUser);
          debugLog('토큰 없이 로컬스토리지 기반 사용자 정보 설정:', localUser);
        } else {
          console.warn('사용자 정보를 찾을 수 없습니다. 로그인이 필요합니다.');
          setCurrentUser(null); // 로그인하지 않은 상태로 설정
        }
      }
    };
    
    getUserFromStorage();
  }, []);

  const fetchPostDetails = useCallback(async () => {
    if (!postId) return;
    setLoadingPost(true);
    setPostError(false);
    try {
      const response = await axios.get<PostDto>(
        `${API_BASE_URL}/detail/${postId}`,
        {
          headers: {
            'Content-Type': 'application/json',
            // JWT 토큰이 있는 경우 추가
            ...(localStorage.getItem('userToken') && {
              'Authorization': `Bearer ${localStorage.getItem('userToken')}`
            })
          }
        }
      );
      setPost(response.data);
      
      // 게시글 정보 로드 후 현재 사용자가 이미 참여(신청)했는지 확인
      if (currentUser && response.data.participants) {
        const isCurrentUserParticipating = response.data.participants.some(
          participant => participant.userId === currentUser.id || 
                         (participant.email && currentUser.email && 
                          participant.email === currentUser.email)
        );
        
        if (isCurrentUserParticipating) {
          debugLog('현재 사용자가 이미 참여 중입니다.');
          setIsParticipated(true);
        } else {
          debugLog('현재 사용자는 아직 참여하지 않았습니다.');
          setIsParticipated(false);
        }
      }
      
      // isAuthor 설정은 위의 useEffect에서 처리하므로 여기서는 로그만 출력
      debugLog('게시글 데이터 로드:', {
        postUser: response.data?.user,
        currentUser,
        participants: response.data.participants
      });
    } catch (error) {
      console.error("Error fetching post details:", error);
      setPostError(true);
    } finally {
      setLoadingPost(false);
    }
  }, [postId, currentUser]); // currentUser 의존성 다시 추가

  const fetchComments = useCallback(async () => {
    if (!postId) return;
    setLoadingComments(true);
    setCommentsError(false);
    setComments([]);
    try {
      const commentsResponse = await axios.get<CommentDto[]>(
        `${API_BASE_URL}/comments/parent/${postId}`,
        {
          headers: {
            'Content-Type': 'application/json',
            // JWT 토큰이 있는 경우 추가
            ...(localStorage.getItem('userToken') && {
              'Authorization': `Bearer ${localStorage.getItem('userToken')}`
            })
          }
        }
      );
      setComments(commentsResponse.data);
    } catch (error) {
      console.error("Error fetching comments:", error);
      setCommentsError(true);
    } finally {
      setLoadingComments(false);
    }
  }, [postId]);

  // 사용자 북마크 목록 조회 및 현재 게시글 북마크 상태 확인
  const checkBookmarkStatus = useCallback(async () => {
    if (!postId || !currentUser) return;
    
    try {
      const response = await axios.get<BookMarkDto[]>(`${API_BASE_URL}/bookmark/read`, {
        headers: {
          // 인증 헤더 추가 (필요한 경우)
          // 'Authorization': `Bearer ${token}`
        }
      });
      
      // 현재 게시글이 북마크되어 있는지 확인
      const bookmarked = response.data.some(
        bookmark => bookmark.postId === Number(postId) && bookmark.status
      );
      
      setIsBookmarked(bookmarked);
    } catch (error) {
      console.error("Error fetching bookmark status:", error);
    }
  }, [postId, currentUser]);

  useEffect(() => {
    fetchPostDetails();
    fetchComments();
  }, [fetchPostDetails, fetchComments]);

  // 북마크 상태 확인
  useEffect(() => {
    if (currentUser) {
      checkBookmarkStatus();
    }
  }, [checkBookmarkStatus, currentUser]);

  // 게시글이 로드된 후 participants 배열과 currentUser를 비교해서 참여 상태 확인
  useEffect(() => {
    if (post?.participants && currentUser) {
      debugLog('게시글 참여자 목록과 현재 사용자 비교', {
        currentUserId: currentUser.id,
        currentUserEmail: currentUser.email,
        participantCount: post.participants.length
      });
      
      // 이메일과 ID로 비교
      const isCurrentUserParticipating = post.participants.some(
        participant => 
          // ID로 비교 (ID가 있는 경우)
          (participant.userId && currentUser.id && participant.userId === currentUser.id) ||
          // 이메일로 비교 (ID가 없거나 테스트 환경에서 ID가 모두 1인 경우 대비)
          (participant.email && currentUser.email && participant.email === currentUser.email)
      );
      
      debugLog('참여 상태 확인 결과', {
        isParticipated: isCurrentUserParticipating
      });
      
      setIsParticipated(isCurrentUserParticipating);
    }
  }, [post, currentUser]);

  // 신청서 데이터 업데이트 함수
  const updateParticipateData = (field: keyof ParticipateCreateRequestDto, value: any) => {
    setParticipateData(prev => ({
      ...prev,
      [field]: value
    }));
  };
  
  // 신청 과정 다음 단계로 이동
  const goToNextStep = () => {
    if (participateStep < 3) {
      setParticipateStep(prev => prev + 1);
    }
  };
  
  // 신청 과정 이전 단계로 이동
  const goToPreviousStep = () => {
    if (participateStep > 1) {
      setParticipateStep(prev => prev - 1);
    } else {
      // 첫 단계에서 뒤로가기는 모달 닫기
      setParticipateDialogOpen(false);
      setParticipateStep(1); // 상태 초기화
    }
  };
  
  // 신청 제출 처리
  const submitParticipation = async () => {
    if (!postId || !currentUser) {
      alert("로그인이 필요한 기능입니다.");
      return;
    }
    
    if (participateData.content.trim().length === 0) {
      alert("신청 내용을 입력해주세요.");
      return;
    }
    
    if (participateData.content.length > 30) {
      alert("신청 내용은 30자 이내로 작성해주세요.");
      return;
    }
    
    setLoadingParticipate(true);
    try {
      // 서버로 전송
      const response = await axios.post<ParticipateDto>(
        `${API_BASE_URL}/${postId}/participate`,
        participateData,
        {
          headers: {
            'Content-Type': 'application/json',
            ...(localStorage.getItem('userToken') && {
              'Authorization': `Bearer ${localStorage.getItem('userToken')}`
            })
          }
        }
      );
      
      debugLog('참여 신청 응답:', response.data);
      setIsParticipated(true);
      setParticipateDialogOpen(false);
      setParticipateStep(1); // 상태 초기화
      setParticipateData({
        content: '',
        gender: false,
        verifySmoker: false,
        verifyGoReturn: true,
      });
      
      // 참여 후 게시글 정보 다시 불러오기
      fetchPostDetails();
      
      alert('신청이 완료되었습니다.');
    } catch (err) {
      console.error("Error participating in post:", err);
      alert("신청 처리 중 오류가 발생했습니다.");
    } finally {
      setLoadingParticipate(false);
    }
  };

  // 북마크 토글 핸들러
  const handleBookmarkToggle = async () => {
    console.log('북마크 토글 시도:', { postId, currentUser });
    
    if (!postId) {
      alert("게시글 정보를 찾을 수 없습니다.");
      return;
    }
    
    // currentUser가 없어도 API 호출 시도 (개발/테스트 환경용)
    setLoadingBookmark(true);
    try {
      console.log('북마크 API 호출 시작');
      const response = await axios.post<BookmarkAddDto>(
        `${API_BASE_URL}/bookmark/${postId}`,
        {}, // 필요한 경우 요청 본문 데이터 추가
        {
          headers: {
            'Content-Type': 'application/json',
            // JWT 토큰이 있는 경우 추가
            ...(localStorage.getItem('token') && {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            })
          }
        }
      );
      
      // 서버 응답 자세히 확인
      console.log("북마크 API 응답:", response.data);
      
      // 북마크 상태 토글
      setIsBookmarked(prev => !prev);
      
      // 서버 응답의 addAndRemove 값에 따라 다른 메시지 표시
      // 대소문자, 앞뒤 공백 등을 고려하여 처리
      const responseValue = response.data.addAndRemove?.trim?.().toUpperCase();
      if (responseValue === "ADD") {
        alert("북마크에 추가되었습니다.");
      } else if (responseValue === "REMOVE") {
        alert("북마크가 해제되었습니다.");
      } else {
        // 응답 값이 예상과 다른 경우, 현재 북마크 상태 기준으로 메시지 표시
        alert(isBookmarked ? "북마크가 해제되었습니다." : "북마크에 추가되었습니다.");
        console.log("예상치 못한 응답 값:", responseValue);
      }
      
      // 북마크 상태 확인 API 다시 호출하여 실제 상태 동기화
      checkBookmarkStatus();
    } catch (error) {
      console.error("Error toggling bookmark:", error);
      alert("북마크 처리 중 오류가 발생했습니다.");
    } finally {
      setLoadingBookmark(false);
    }
  };

  const authorImage = post?.user?.profileImageUrl || 'https://via.placeholder.com/40';
  const authorNickname = post?.user?.nickname || '작성자';
  const authorIdentifier = post?.user?.studentId || (post?.user?.id ? '학번 정보 없음' : '작성자 정보 없음');

  // 답글 달기 버튼 클릭 핸들러
  const handleReplyClick = (commentId: number) => {
    // 해당 댓글 찾기 (중첩된 댓글도 찾을 수 있어야 함)
    const findComment = (comments: CommentDto[], targetId: number): CommentDto | null => {
      for (const comment of comments) {
        if (comment.commentId === targetId) {
          return comment;
        }
        if (comment.childComments && comment.childComments.length > 0) {
          const found = findComment(comment.childComments, targetId);
          if (found) return found;
        }
      }
      return null;
    };

    const targetComment = findComment(comments, commentId);
    if (targetComment) {
      setReplyingToCommentId(commentId);
      setReplyingToCommentInfo({
        id: commentId,
        content: targetComment.content
      });
      
      // 댓글 입력창으로 포커스 이동
      setTimeout(() => {
        if (commentInputRef.current) {
          commentInputRef.current.focus();
        }
      }, 100);
    }
  };

  // 답글 취소 핸들러
  const handleCancelReply = () => {
    setReplyingToCommentId(null);
    setReplyingToCommentInfo(null);
  };

  const handleCommentSubmit = async () => {
    if (!newComment.trim()) return;
    setIsSubmittingComment(true);
    try {
      // currentUser 상태 사용 (이미 useEffect에서 설정됨)
      // 만약 currentUser 값이 없다면 기본값 설정
      let currentUserEmail = currentUser?.email || "tempUser@example.com";
      let currentUserId = currentUser?.id || null;
      
      console.log('댓글 작성 시 사용자 정보:', {
        id: currentUserId,
        email: currentUserEmail
      });

      const commentRequestDto = {
        content: newComment,
      };

      // 부모 댓글 또는 자식 댓글 API 호출 분기
      let response;
      if (replyingToCommentId) {
        // 자식 댓글 (대댓글) 생성 API 호출
        response = await axios.post<CommentDto>(
          `${API_BASE_URL}/comments/child/${replyingToCommentId}`,
          commentRequestDto,
          {
            headers: {
              'Content-Type': 'application/json',
              // JWT 토큰이 있는 경우 추가
              ...(localStorage.getItem('userToken') && {
                'Authorization': `Bearer ${localStorage.getItem('userToken')}`
              })
            },
          }
        );
      } else {
        // 부모 댓글 생성 API 호출
        response = await axios.post<CommentDto>(
          `${API_BASE_URL}/comments/parent/${postId}`,
          commentRequestDto,
          {
            headers: {
              'Content-Type': 'application/json',
              // JWT 토큰이 있는 경우 추가
              ...(localStorage.getItem('userToken') && {
                'Authorization': `Bearer ${localStorage.getItem('userToken')}`
              })
            },
          }
        );
      }
      
      // 댓글 목록 새로고침
      fetchComments();
      
      // 입력창 초기화 및 답글 상태 초기화
      setNewComment('');
      setReplyingToCommentId(null);
      setReplyingToCommentInfo(null);
    } catch (error) {
      console.error("Error submitting comment:", error);
      alert('댓글 등록에 실패했습니다.');
    } finally {
      setIsSubmittingComment(false);
    }
  };

  // 게시글 작성자와 현재 사용자 비교를 위한 useEffect 추가
  useEffect(() => {
    // post와 currentUser가 모두 있을 때만 작성자 비교
    if (post?.user && currentUser) {
      // 오직 이메일로만 비교 (ID는 테스트용으로 1로 같게 설정되어 있어서 비교에서 제외)
      let isMatched = false;
      
      // 이메일로 비교
      if (currentUser.email && post.user.email) {
        if (currentUser.email === post.user.email) {
          isMatched = true;
          console.log('작성자 비교: 이메일 일치');
        } else {
          console.log('작성자 비교: 이메일 불일치', {
            currentUserEmail: currentUser.email,
            postUserEmail: post.user.email
          });
        }
      } else {
        console.log('작성자 비교: 이메일 정보 없음', {
          hasCurrentUserEmail: !!currentUser.email,
          hasPostUserEmail: !!post.user.email
        });
      }
      
      // ID 비교 제거 (테스트 환경에서는 모든 ID가 1로 설정되어 있음)
      
      console.log('작성자 비교 최종 결과:', {
        isAuthor: isMatched,
        currentUser: {
          id: currentUser.id,
          email: currentUser.email
        },
        postUser: {
          id: post.user.id,
          email: post.user.email
        }
      });
      
      setIsAuthor(isMatched);
    }
  }, [post, currentUser]);

  // 참여 취소 핸들러
  const handleCancelParticipation = async () => {
    if (!postId || !currentUser) {
      alert("로그인이 필요한 기능입니다.");
      return;
    }
    
    if (!window.confirm('정말로 신청을 취소하시겠습니까?')) {
      return;
    }
    
    setLoadingParticipate(true);
    try {
      debugLog('참여 취소 시작', { postId });
      
      const response = await axios.patch<ParticipateMsgDto>(
        `${API_BASE_URL}/${postId}/participateCancel`,
        {},
        {
          headers: {
            'Content-Type': 'application/json',
            ...(localStorage.getItem('userToken') && {
              'Authorization': `Bearer ${localStorage.getItem('userToken')}`
            })
          }
        }
      );
      
      debugLog('참여 취소 응답:', response.data);
      setIsParticipated(false);
      
      // 취소 후 게시글 정보 다시 불러오기
      fetchPostDetails();
      
      alert(response.data.msg || '신청이 취소되었습니다.');
    } catch (error) {
      console.error("Error canceling participation:", error);
      alert("신청 취소 중 오류가 발생했습니다.");
    } finally {
      setLoadingParticipate(false);
    }
  };

  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setMenuAnchorEl(event.currentTarget);
  };
  const handleMenuClose = () => {
    setMenuAnchorEl(null);
  };
  const handleEdit = () => {
    handleMenuClose();
    navigate(`/post/edit/${postId}`);
  };
  const handleDeleteClick = () => {
    handleMenuClose();
    setShowDeleteDialog(true);
  };
  const handleDelete = async () => {
    // 삭제 API 호출
    try {
      const token = localStorage.getItem('userToken');
      await axios.patch(`${API_BASE_URL}/post/delete/${postId}`, {}, {
        headers: {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        }
      });
      alert('삭제 완료!');
      navigate('/');
    } catch (e) {
      alert('삭제에 실패했습니다.');
    } finally {
      setShowDeleteDialog(false);
    }
  };

  if (loadingPost) {
    return <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '80vh' }}><CircularProgress /></Box>;
  }

  if (postError || !post) {
    return (
      <Box sx={{ textAlign: 'center', mt: 4 }}>
        <Typography variant="h6" color="error">게시글을 불러올 수 없습니다.</Typography>
        <Button variant="outlined" onClick={() => navigate(-1)} sx={{ mt: 2 }}>뒤로가기</Button>
      </Box>
    );
  }

  const timeAgo = dayjs(post.createDate).fromNow();

  return (
    <DetailPageContainer>
      <TopAppBar>
        <IconButton onClick={() => navigate(-1)}>
          <ArrowBack />
        </IconButton>
        <Typography variant="h6" component="div" sx={{ flexGrow: 1, textAlign: 'center', fontSize: '1rem'}}>
          게시물
        </Typography>
        {isAuthor && (
          <>
            <IconButton onClick={handleMenuOpen}>
          <MoreVert />
        </IconButton>
            <Menu
              anchorEl={menuAnchorEl}
              open={Boolean(menuAnchorEl)}
              onClose={handleMenuClose}
              anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
              transformOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
              <MenuItem onClick={handleEdit}>수정</MenuItem>
              <MenuItem onClick={handleDeleteClick} sx={{ color: 'error.main' }}>삭제</MenuItem>
            </Menu>
            <Dialog open={showDeleteDialog} onClose={() => setShowDeleteDialog(false)}>
              <DialogTitle>정말 삭제하시겠습니까?</DialogTitle>
              <DialogActions>
                <Button onClick={() => setShowDeleteDialog(false)}>취소</Button>
                <Button color="error" onClick={handleDelete}>
                  삭제
                </Button>
              </DialogActions>
            </Dialog>
          </>
        )}
      </TopAppBar>

      <Container maxWidth="sm" disableGutters sx={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <PostInfoContainer>
          <AuthorInfo sx={{ marginLeft: '8px', marginTop: '8px' }}>
            <Avatar src={authorImage} alt={authorNickname} sx={{ width: 32, height: 32}} />
            <Box>
              <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>{authorNickname}</Typography>
              <Typography variant="caption" color="text.secondary">{authorIdentifier}</Typography>
            </Box>
          </AuthorInfo>

          <PostContent>
            <Typography variant="h5" component="h1" sx={{ fontWeight: 'bold', fontSize: '1.25rem', mb: 3, marginLeft: '8px' }}>
              {post.title}
            </Typography>
            <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap', color: 'text.primary', mb: 5, fontSize: '0.9375rem', marginLeft: '8px' }}>
              {post.content}
            </Typography>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', mb: 1, gap:0.3, alignItems: 'right' }}>
              <StyledChip 
                size="small" 
                color="primary"
                icon=<DirectionsCar sx={{ color: '#2D68FF' }} />
                label={post.category?.categoryName}
              />
              <StyledChip 
                size="small" 
                color="primary"
                icon={post.verifyGoReturn ? <SunnyIcon fontSize="small" /> : <NightIcon fontSize="small" />}
                label={post.verifyGoReturn ? "등교" : "하교"}
              />
              <StyledChip 
                size="small" 
                color="primary"
                icon={post.gender ? <WomanIcon fontSize="small" /> : <ManIcon fontSize="small" />}
                label={post.gender ? "여성" : "남성"} 
              />
              <StyledChip 
                size="small" 
                color="primary"
                icon={post.verifySmoker ? <SmokingIcon fontSize="small" /> : <NoSmokingIcon fontSize="small" />}
                label={post.verifySmoker ? "흡연 O" : "흡연 X"} 
              />
            </Box>
            <Typography variant="caption" color="text.secondary">
              {timeAgo}
            </Typography>
          </PostContent>

          <Divider sx={{ my: 0.5 }} />

          <InfoSection>
            <InfoRow><Group /><Typography>{`${post.participantsCount || 0}/${post.numberOfPassengers}명`}</Typography></InfoRow>
            <InfoRow><LocalOffer /><Typography>{post.cost?.toLocaleString() || 0}원</Typography></InfoRow>
            <InfoRow><EventIcon /><Typography>{dayjs(post.targetDate).format('YY.MM.DD (ddd)')} {post.targetTime}</Typography></InfoRow>
            <LocationRow onClick={() => navigate('/search', { state: { selectedPlace: { name: post.title, address: post.location, postData: post } } } )}>
              <Box sx={{display: 'flex', alignItems: 'center', gap: 1}}>
                <LocationOn color="primary" />
                <Box>
                  <Typography sx={{fontSize: '0.875rem', fontWeight: 500, color: 'text.primary'}}>{post.location?.split('→')[0]?.trim() || post.location}</Typography>
                  {post.location?.includes('→') && 
                    <Typography sx={{fontSize: '0.75rem', color: 'text.secondary'}}>{post.location?.split('→')[1]?.trim()}</Typography>}
                </Box>
              </Box>
              <ArrowBack sx={{ transform: 'rotate(180deg)', color: 'text.disabled'}} />
            </LocationRow>
          </InfoSection>
        </PostInfoContainer>

        <CommentsSection>
          <Typography variant="h6" sx={{ fontWeight: 'medium', fontSize: '1rem', mb: 0.5, display: 'flex', alignItems: 'center' }}>
            댓글
            <Typography component="span" variant="subtitle2" color="primary" sx={{ fontWeight: 700, fontSize: '1rem', ml: 1 }}>
              {comments.length}
            </Typography>
          </Typography>
          {replyingToCommentInfo && (
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'space-between',
              backgroundColor: 'action.hover',
              borderRadius: '4px',
              p: 1,
              mb: 1
            }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Reply fontSize="small" color="primary" />
                <Typography variant="body2" sx={{ fontWeight: 500 }}>
                  답글 작성 중
                </Typography>
                <Typography 
                  variant="body2" 
                  sx={{ 
                    color: 'text.secondary',
                    maxWidth: '200px',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap'
                  }}
                >
                  {replyingToCommentInfo.content}
                </Typography>
              </Box>
              <IconButton size="small" onClick={handleCancelReply}>
                <CloseIcon fontSize="small" />
              </IconButton>
            </Box>
          )}
            <CommentInputBox
              fullWidth
              multiline
              minRows={1}
              maxRows={4}
              variant="outlined"
              placeholder={replyingToCommentId ? "답글을 입력하세요..." : "댓글을 입력하세요..."}
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              disabled={isSubmittingComment}
              inputRef={commentInputRef}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton
              color="primary"
              onClick={handleCommentSubmit}
              disabled={isSubmittingComment || !newComment.trim()}
                    edge="end"
            >
              {isSubmittingComment ? <CircularProgress size={24} color="inherit" /> : <Send />}
                  </IconButton>
                </InputAdornment>
              ),
            }}
          />
          
          {loadingComments && (
            <Box sx={{ display: 'flex', justifyContent: 'center', my: 2 }}>
              <CircularProgress />
            </Box>
          )}
          {commentsError && (
            <Typography color="error" sx={{ textAlign: 'center', my: 2 }}>
              댓글을 불러오는 중 오류가 발생했습니다.
            </Typography>
          )}
          {!loadingComments && !commentsError && comments.length === 0 && (
            <Typography sx={{ textAlign: 'center', color: 'text.secondary', my: 2 }}>
              아직 댓글이 없습니다. 첫 댓글을 남겨보세요!
            </Typography>
          )}
          <List dense sx={{ bgcolor: 'background.paper', borderRadius: '8px', p:0 }}>
            {comments.map((comment) => (
              <React.Fragment key={comment.commentId}>
                <CommentNode 
                  comment={comment} 
                  level={0} 
                  onReply={handleReplyClick}
                />
                <Divider component="li" sx={{ ml: comment.childComments && comment.childComments.length > 0 ? 0 : '56px' }} />
              </React.Fragment>
            ))}
          </List>
        </CommentsSection>

        <Paper
          elevation={1}
          sx={{
            borderRadius: '0 0 8px 8px',
            boxShadow: '0px -2px 8px rgba(0,0,0,0.04)',
            border: '1px solid #eee',
            p: 1,
            display: 'flex',
            gap: 1,
            alignItems: 'center',
            background: '#fff',
            width: '100%',
            mt: 0,
            flexShrink: 0,
          }}
        >
          <IconButton 
            sx={{ 
              border: '1px solid #E0E0E0', 
              borderRadius: '8px', 
              width: 48, 
              height: 48,
              color: isBookmarked ? 'primary.main' : 'inherit',
              background: 'background.paper',
              flexShrink: 0,
              p: 0,
            }}
            onClick={handleBookmarkToggle}
            disabled={loadingBookmark}
          >
            {loadingBookmark ? (
              <CircularProgress size={24} />
            ) : isBookmarked ? (
              <Bookmark />
            ) : (
              <BookmarkBorder />
            )}
          </IconButton>
          {isAuthor ? (
            <Button 
              variant="outlined" 
              color="primary" 
              fullWidth 
              sx={{ 
                height: 48, 
                fontSize: '1rem', 
                fontWeight: 600,
                backgroundColor: 'background.paper',
                borderRadius: '8px',
                minWidth: 0,
                p: 0,
              }}
              onClick={() => navigate(`/applications/${postId}`)}
            >
              받은 신청 보러가기
            </Button>
          ) : (
            <Button 
              variant={isParticipated ? "outlined" : "contained"}
              color={isParticipated ? "error" : "primary"}
              fullWidth 
              sx={{ 
                height: 48, 
                fontSize: '1rem', 
                fontWeight: 600,
                borderRadius: '8px',
                minWidth: 0,
                p: 0,
                backgroundColor: isParticipated ? 'background.paper' : undefined
              }}
              onClick={isParticipated ? handleCancelParticipation : () => setParticipateDialogOpen(true)}
              disabled={loadingParticipate}
            >
              {loadingParticipate ? (
                <CircularProgress size={24} color="inherit" />
              ) : isParticipated ? (
                "신청 취소하기"
              ) : (
                "신청하기"
              )}
            </Button>
          )}
        </Paper>
      </Container>

      <Dialog 
        open={participateDialogOpen} 
        onClose={() => {
          setParticipateDialogOpen(false);
          setParticipateStep(1); // 모달 닫을 때 단계 초기화
          setParticipateData({
            content: '',
            gender: false,
            verifySmoker: false,
            verifyGoReturn: true,
          });
        }}
        fullWidth
        maxWidth="xs"
        PaperProps={{
          sx: { borderRadius: 2 }
        }}
      >
        <DialogTitle sx={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          borderBottom: '1px solid',
          borderColor: 'divider',
          pb: 1
        }}>
          <Typography variant="h6">
            {participateStep === 1 && '신청에 필요한 정보를 입력해주세요'}
            {participateStep === 2 && '추가 내용을 작성해주세요'}
            {participateStep === 3 && '신청 완료'}
          </Typography>
          <IconButton 
            edge="end" 
            color="inherit" 
            onClick={() => {
              setParticipateDialogOpen(false);
              setParticipateStep(1); // 모달 닫을 때 단계 초기화
            }} 
            aria-label="close"
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        
        <DialogContent sx={{ py: 2 }}>
          <Box sx={{ mb: 2, display: 'flex', justifyContent: 'center' }}>
            <Typography variant="body2" color="text.secondary">
              {participateStep} / 3
            </Typography>
          </Box>
          
          {participateStep === 1 && (
            <>
              <Box sx={{ mb: 3 }}>
                <Typography variant="subtitle1" sx={{ mb: 1, fontWeight: 'medium' }}>
                  성별
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Button 
                    variant={participateData.gender === false ? "contained" : "outlined"}
                    fullWidth
                    onClick={() => updateParticipateData('gender', false)}
                  >
                    남성
                  </Button>
                  <Button 
                    variant={participateData.gender === true ? "contained" : "outlined"}
                    fullWidth
                    onClick={() => updateParticipateData('gender', true)}
                  >
                    여성
                  </Button>
                </Box>
              </Box>
              
              <Box sx={{ mb: 3 }}>
                <Typography variant="subtitle1" sx={{ mb: 1, fontWeight: 'medium' }}>
                  흡연 여부
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Button 
                    variant={participateData.verifySmoker === false ? "contained" : "outlined"}
                    fullWidth
                    onClick={() => updateParticipateData('verifySmoker', false)}
                  >
                    비흡연
                  </Button>
                  <Button 
                    variant={participateData.verifySmoker === true ? "contained" : "outlined"}
                    fullWidth
                    onClick={() => updateParticipateData('verifySmoker', true)}
                  >
                    흡연
                  </Button>
                </Box>
              </Box>
            </>
          )}
          
          {participateStep === 2 && (
            <>
              <Box sx={{ mb: 3 }}>
                <Typography variant="subtitle1" sx={{ mb: 1, fontWeight: 'medium' }}>
                  주기를 선택해주세요
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Button 
                    variant={participateData.verifyGoReturn === true ? "contained" : "outlined"}
                    fullWidth
                    onClick={() => updateParticipateData('verifyGoReturn', true)}
                  >
                    등교
                  </Button>
                  <Button 
                    variant={participateData.verifyGoReturn === false ? "contained" : "outlined"}
                    fullWidth
                    onClick={() => updateParticipateData('verifyGoReturn', false)}
                  >
                    하교
                  </Button>
                </Box>
              </Box>
              
              <Box sx={{ mb: 1 }}>
                <Typography variant="subtitle1" sx={{ mb: 1, fontWeight: 'medium' }}>
                  메시지 입력
                </Typography>
                <TextField
                  fullWidth
                  variant="outlined"
                  placeholder="메시지를 입력해주세요 (30자 이내)"
                  value={participateData.content}
                  onChange={(e) => updateParticipateData('content', e.target.value)}
                  inputProps={{ 
                    maxLength: 30,
                    sx: { fontSize: '0.9rem' }
                  }}
                  helperText={`${participateData.content.length}/30`}
                  FormHelperTextProps={{
                    sx: { textAlign: 'right', margin: 0, mt: 0.5 }
                  }}
                />
              </Box>
            </>
          )}
          
          {participateStep === 3 && (
            <Box sx={{ 
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              py: 4
            }}>
              <CheckCircleIcon color="primary" sx={{ fontSize: 64, mb: 2 }} />
              <Typography variant="h6" gutterBottom>
                신청 완료
              </Typography>
              <Typography variant="body2" color="text.secondary" align="center">
                MIO 서비스의 서비스를 신청해주셔서 감사합니다.
              </Typography>
            </Box>
          )}
        </DialogContent>
        
        <DialogActions sx={{ px: 3, py: 2, borderTop: '1px solid', borderColor: 'divider' }}>
          {participateStep !== 3 ? (
            <>
              <Button onClick={goToPreviousStep} 
                variant="outlined" 
                sx={{ flex: 1 }}
              >
                {participateStep === 1 ? '취소' : '이전'}
              </Button>
              <Button 
                onClick={participateStep === 2 ? submitParticipation : goToNextStep} 
                variant="contained" 
                color="primary"
                sx={{ flex: 1 }}
                disabled={participateStep === 2 && participateData.content.trim() === ''}
              >
                {participateStep === 2 ? '신청' : '다음'}
              </Button>
            </>
          ) : (
            <Button 
              onClick={() => {
                setParticipateDialogOpen(false);
                setParticipateStep(1);
              }} 
              variant="contained" 
              color="primary"
              fullWidth
            >
              확인
            </Button>
          )}
        </DialogActions>
      </Dialog>
    </DetailPageContainer>
  );
};

export default PostDetailPage; 