import React from 'react';
import { 
  Box, 
  Typography, 
  ListItem, 
  useTheme,
} from '@mui/material';
import { Person, DirectionsCar, Place, CalendarToday } from '@mui/icons-material';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';

// Profile에서 사용하는 PostDto 타입 정의
// 기존 PostDto와 호환을 위한 인터페이스
export interface PostCardData {
  postId: number;
  title: string;
  content: string;
  createDate: string;
  targetDate?: string;
  targetTime?: string;
  category?: {
    id: number;
    name: string;
  };
  numberOfPassengers: number;
  user?: {
    id: number;
    email?: string;
    username?: string;
  };
  viewCount: number;
  latitude?: number;
  longitude?: number;
  bookMarkCount?: number;
  participantsCount: number;
  location: string;
  cost: number;
  isDeleteYN?: string;
  postType?: string;
  region3Depth?: string;
  gender?: boolean;
  verifySmoker?: boolean;
  verifyGoReturn?: boolean;
  participants?: any[];
  startLocation?: string;
  endLocation?: string;
  
  // src/types/post.ts의 PostDto와 호환을 위한 추가 필드
  commentCount?: number;
  postStatus?: string;
  modifiedDate?: string;
}

interface PostCardProps {
  post: PostCardData;
  onClick?: (postId: number) => void;
  isMobile?: boolean; // 외부에서 미디어 쿼리 결과를 주입할 수 있도록
  showCategoryName?: boolean; // 카테고리 이름 표시 여부
}

/**
 * 재사용 가능한 게시글 카드 컴포넌트
 * 세로 타임라인과 아이콘이 있는 게시글 카드를 표시합니다.
 */
const PostCard: React.FC<PostCardProps> = ({ post, onClick, isMobile, showCategoryName = false }) => {
  const theme = useTheme();
  
  // 반응형 스타일 값 계산
  const styles = {
    iconSize: isMobile ? '16px' : '20px',
    fontSize: {
      title: isMobile ? '14px' : '16px',
      body: isMobile ? '12px' : '14px',
    },
    spacing: {
      icon: isMobile ? 0.8 : 1,
      section: isMobile ? 0.8 : 1.5,
      contentPadding: isMobile ? 1.5 : 2,
    },
    sidebarWidth: isMobile ? '50px' : '60px',
    contentMargin: isMobile ? '55px' : '70px',
  };
  
  // 테마 색상
  const primaryColor = theme.palette.primary.main;
  const iconColor = theme.palette.grey[500];
  
  // 날짜 포맷팅
  const formatDate = (dateString?: string): string => {
    if (!dateString) return '-';
    return dayjs(dateString).format('YY.MM.DD (ddd)');
  };

  // 시간 포맷팅
  const formatTime = (timeString?: string): string => {
    if (!timeString) return '';
    return dayjs(`2000-01-01T${timeString}`).format('HH:mm');
  };
  
  // 클릭 핸들러
  const handleClick = () => {
    if (onClick) {
      onClick(post.postId);
    }
  };

  // 출발지와 도착지 분리
  const location = post.location || '';
  let startLocation = post.startLocation || location;
  let endLocation = post.endLocation || '';
  
  // startLocation이나 endLocation이 없고, location에서 출발/도착지를 추출할 수 있는 경우
  if (!post.startLocation && !post.endLocation && location.includes('→')) {
    const locations = location.split('→').map(loc => loc.trim());
    if (locations.length >= 2) {
      startLocation = locations[0];
      endLocation = locations[1];
    }
  }

  return (
    <ListItem 
      button
      alignItems="flex-start"
      onClick={handleClick}
      sx={{ 
        p: 0, 
        position: 'relative',
        borderBottom: `1px solid ${theme.palette.divider}`,
        '&:last-child': {
          borderBottom: 'none',
        },
        borderRadius: theme.shape.borderRadius * 3,
        backgroundColor: theme.palette.background.paper,
        boxShadow: '0px 2px 8px rgba(0, 0, 0, 0.08)',
        mb: 2,
        overflow: 'hidden'
      }}
    >
      {/* 왼쪽 파란색 선과 아이콘 */}
      <Box sx={{ 
        position: 'absolute',
        left: 0,
        top: 0,
        bottom: 0,
        width: styles.sidebarWidth,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
      }}>
        {/* 차 아이콘 */}
        <Box sx={{ 
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          mt: 2,
          position: 'relative',
          zIndex: 2
        }}>
          <DirectionsCar sx={{ color: primaryColor, fontSize: styles.iconSize }} />
        </Box>
        
        {/* 세로선 */}
        <Box sx={{ 
          width: '2px', 
          bgcolor: primaryColor, 
          position: 'absolute',
          top: theme.spacing(4.375), // 35px를 테마 스페이싱으로 변환
          bottom: theme.spacing(2.25), // 18px를 테마 스페이싱으로 변환
          zIndex: 1
        }} />
        
        {/* 동그라미 (선 끝에) */}
        <Box sx={{
          position: 'absolute',
          bottom: theme.spacing(2.25), // 18px를 테마 스페이싱으로 변환
          width: '6px',
          height: '6px',
          borderRadius: '50%',
          bgcolor: primaryColor,
          zIndex: 2
        }} />
      </Box>

      {/* 컨텐츠 */}
      <Box sx={{ 
        ml: styles.contentMargin, 
        py: styles.spacing.contentPadding,
        pr: theme.spacing(3),
        width: `calc(100% - ${styles.contentMargin})`,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center'
      }}>
        {/* 제목 */}
        <Typography 
          variant="body1" 
          fontWeight="bold" 
          sx={{ 
            mb: styles.spacing.section, 
            fontSize: styles.fontSize.title,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
          }}
        >
          {post.title}
        </Typography>

        {/* 날짜/시간 */}
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          mb: styles.spacing.section,
        }}>
          <CalendarToday sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
          <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
            {formatDate(post.targetDate)} {formatTime(post.targetTime)}
          </Typography>
        </Box>

        {/* 장소 */}
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          mb: styles.spacing.section,
        }}>
          <Place sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
          <Typography 
            variant="body2" 
            color="text.secondary" 
            sx={{ 
              fontSize: styles.fontSize.body,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 1,
              WebkitBoxOrient: 'vertical',
            }}
          >
            {startLocation}
            {endLocation ? ` → ${endLocation}` : ''}
          </Typography>
        </Box>

        {/* 인원 */}
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          ...(showCategoryName && post.category ? { mb: styles.spacing.section } : {})
        }}>
          <Person sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
          <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
            {post.participantsCount}/{post.numberOfPassengers}
          </Typography>
        </Box>
        
        {/* 카테고리 이름 - showCategoryName이 true이고 카테고리가 있을 때만 표시 */}
        {showCategoryName && post.category && (
          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center',
          }}>
            <DirectionsCar sx={{ color: iconColor, fontSize: styles.iconSize, mr: styles.spacing.icon }} />
            <Typography variant="body2" color="text.secondary" sx={{ fontSize: styles.fontSize.body }}>
              {post.category.name}
            </Typography>
          </Box>
        )}
      </Box>
    </ListItem>
  );
};

export default PostCard; 