import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Box, Button, Container, Paper, Typography, TextField, MenuItem, Grid, IconButton, Dialog, DialogTitle, DialogActions, CircularProgress
} from '@mui/material';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import dayjs from 'dayjs';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:8080';

const categoryOptions = [
  { id: 1, name: '카풀' },
  { id: 2, name: '택시' },
];

const PostEditPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [post, setPost] = useState<any>(null);
  const [form, setForm] = useState({
    title: '',
    content: '',
    categoryId: '',
    targetDate: '',
    targetTime: '',
    numberOfPassengers: '',
    cost: '',
    region3Depth: '',
  });

  useEffect(() => {
    const fetchPost = async () => {
      setLoading(true);
      try {
        const token = localStorage.getItem('userToken');
        const res = await axios.get(`${API_BASE_URL}/detail/${id}`, {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        });
        setPost(res.data);
        setForm({
          title: res.data.title || '',
          content: res.data.content || '',
          categoryId: res.data.category?.categoryId ? String(res.data.category.categoryId) : '',
          targetDate: res.data.targetDate || '',
          targetTime: res.data.targetTime || '',
          numberOfPassengers: res.data.numberOfPassengers || '',
          cost: res.data.cost || '',
          region3Depth: res.data.region3Depth || '',
        });
      } catch (e) {
        alert('게시글 정보를 불러오지 못했습니다.');
        navigate(-1);
      } finally {
        setLoading(false);
      }
    };
    fetchPost();
  }, [id, navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const token = localStorage.getItem('userToken');
      await axios.patch(`${API_BASE_URL}/post/${id}`, form, {
        headers: {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        }
      });
      alert('수정 완료!');
      navigate(`/post/${id}`);
    } catch (e) {
      alert('수정에 실패했습니다.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      const token = localStorage.getItem('userToken');
      await axios.patch(`${API_BASE_URL}/post/delete/${id}`, {}, {
        headers: {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        }
      });
      alert('삭제 완료!');
      navigate('/');
    } catch (e) {
      alert('삭제에 실패했습니다.');
    } finally {
      setDeleting(false);
      setShowDeleteDialog(false);
    }
  };

  if (loading) return <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '80vh' }}><CircularProgress /></Box>;
  if (!post) return null;

  return (
    <Container maxWidth="sm" sx={{ pt: 2, pb: 8 }}>
      <Paper elevation={0} sx={{ borderRadius: '12px', p: 3, position: 'relative' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
          <Typography variant="h6" fontWeight="bold">게시글 수정</Typography>
          <IconButton onClick={() => setShowMenu(!showMenu)}>
            <MoreVertIcon />
          </IconButton>
          {showMenu && (
            <Box sx={{ position: 'absolute', top: 48, right: 16, bgcolor: 'background.paper', boxShadow: 2, borderRadius: 1, zIndex: 10 }}>
              <Button color="error" fullWidth onClick={() => setShowDeleteDialog(true)}>삭제</Button>
            </Box>
          )}
        </Box>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <TextField
              label="제목"
              name="title"
              value={form.title}
              onChange={handleChange}
              fullWidth
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="내용"
              name="content"
              value={form.content}
              onChange={handleChange}
              fullWidth
              multiline
              minRows={4}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              select
              label="카테고리"
              name="categoryId"
              value={form.categoryId}
              onChange={handleChange}
              fullWidth
              required
            >
              {categoryOptions.map(opt => (
                <MenuItem key={opt.id} value={opt.id}>{opt.name}</MenuItem>
              ))}
            </TextField>
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="날짜"
              name="targetDate"
              type="date"
              value={form.targetDate}
              onChange={handleChange}
              fullWidth
              InputLabelProps={{ shrink: true }}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="시간"
              name="targetTime"
              type="time"
              value={form.targetTime}
              onChange={handleChange}
              fullWidth
              InputLabelProps={{ shrink: true }}
              required
            />
          </Grid>
          <Grid item xs={6} sm={6}>
            <TextField
              label="탑승 인원"
              name="numberOfPassengers"
              type="number"
              value={form.numberOfPassengers}
              onChange={handleChange}
              fullWidth
              required
            />
          </Grid>
          <Grid item xs={6} sm={6}>
            <TextField
              label="비용"
              name="cost"
              type="number"
              value={form.cost}
              onChange={handleChange}
              fullWidth
              required
            />
          </Grid>
        </Grid>
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 4, gap: 2 }}>
          <Button variant="contained" color="primary" onClick={handleSave} disabled={saving}>
            {saving ? <CircularProgress size={20} /> : '저장'}
          </Button>
        </Box>
        <Dialog open={showDeleteDialog} onClose={() => setShowDeleteDialog(false)}>
          <DialogTitle>정말 삭제하시겠습니까?</DialogTitle>
          <DialogActions>
            <Button onClick={() => setShowDeleteDialog(false)}>취소</Button>
            <Button color="error" onClick={handleDelete} disabled={deleting}>
              {deleting ? <CircularProgress size={20} /> : '삭제'}
            </Button>
          </DialogActions>
        </Dialog>
      </Paper>
    </Container>
  );
};

export default PostEditPage; 