import React from 'react';
import { Box, Typography, Paper } from '@mui/material';
import { SentimentVerySatisfied, SentimentSatisfied, SentimentDissatisfied } from '@mui/icons-material';
import { MannerDto } from '../types/manner';
import dayjs from 'dayjs';

interface ReceivedReviewCardProps {
  review: MannerDto;
}

const icons = [
  { value: 'GOOD', icon: SentimentVerySatisfied },
  { value: 'NORMAL', icon: SentimentSatisfied },
  { value: 'BAD', icon: SentimentDissatisfied },
];

const iconColor = (selected: boolean) => selected ? '#1976d2' : '#bdbdbd';

const ReceivedReviewCard: React.FC<ReceivedReviewCardProps> = ({ review }) => (
  <Paper elevation={0} sx={{ p: 3, mb: 2, border: '1px solid #eee', borderRadius: 2, width: '100%', position: 'relative' }}>
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
      {icons.map(({ value, icon: Icon }) => (
        <Icon key={value} sx={{ fontSize: 32, color: iconColor(value === review.manner) }} />
      ))}
    </Box>
    <Typography variant="body1" align="left" sx={{ wordBreak: 'keep-all' }}>{review.content}</Typography>
    <Typography variant="caption" color="text.secondary" sx={{ position: 'absolute', right: 16, bottom: 12 }}>
      {dayjs(review.createDate).format('YYYY.MM.DD')}
    </Typography>
  </Paper>
);

export default ReceivedReviewCard; 