import React, { useState, useEffect } from 'react';
import { 
  Popover, 
  List, 
  ListItem, 
  ListItemText, 
  Typography, 
  Box, 
  CircularProgress, 
  IconButton,
  Badge,
  Divider,
  Button
} from '@mui/material';
import { NotificationsOutlined, AccessTime, ArrowForward } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import dayjs from 'dayjs';
import 'dayjs/locale/ko';
import relativeTime from 'dayjs/plugin/relativeTime';

// dayjs 설정
dayjs.extend(relativeTime);
dayjs.locale('ko');

// API 기본 URL
const API_BASE_URL = 'http://localhost:8080';

// 로컬 스토리지 키 - 읽은 알림 목록 저장용
const READ_NOTIFICATIONS_KEY = 'read_notifications';

// AlarmDto 타입 정의
interface AlarmDto {
  id: number;
  createDate: string; // ISO 문자열로 받음
  content: string;
  postId: number;
  userId: number;
  isRead?: boolean; // 읽음 상태 표시 (서버에서 제공하지 않을 경우 클라이언트에서 관리)
}

interface NotificationsProps {
  onNotificationClick?: (postId: number) => void;
}

const Notifications = ({ onNotificationClick }: NotificationsProps): React.ReactElement => {
  const navigate = useNavigate();
  const [anchorEl, setAnchorEl] = useState<HTMLButtonElement | null>(null);
  const [notifications, setNotifications] = useState<AlarmDto[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [unreadCount, setUnreadCount] = useState<number>(0);
  
  // 로컬 스토리지에서 읽은 알림 ID 목록을 가져오는 함수
  const getReadNotificationsFromStorage = (): number[] => {
    const storedData = localStorage.getItem(READ_NOTIFICATIONS_KEY);
    if (storedData) {
      try {
        return JSON.parse(storedData);
      } catch (e) {
        console.error('읽은 알림 데이터 파싱 오류:', e);
      }
    }
    return [];
  };
  
  // 로컬 스토리지에 읽은 알림 ID 목록을 저장하는 함수
  const saveReadNotificationsToStorage = (ids: number[]) => {
    localStorage.setItem(READ_NOTIFICATIONS_KEY, JSON.stringify(ids));
  };
  
  const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    setAnchorEl(event.currentTarget);
    fetchNotifications();
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  // 알림 클릭 시 읽음 처리하고 해당 게시글로 이동
  const handleNotificationClick = async (notification: AlarmDto) => {
    try {
      // 1. 서버 API를 호출하여 읽음 처리 (API가 있는 경우)
      await markNotificationAsRead(notification.id);
      
      // 2. 로컬에서도 읽음 처리
      markNotificationAsReadLocally(notification.id);
      
      // 3. 게시글로 이동
      if (onNotificationClick) {
        onNotificationClick(notification.postId);
      }
      handleClose();
    } catch (err) {
      console.error('알림 읽음 처리 실패:', err);
      // API 실패해도 로컬에서는 읽음 처리하고 페이지 이동
      markNotificationAsReadLocally(notification.id);
      if (onNotificationClick) {
        onNotificationClick(notification.postId);
      }
      handleClose();
    }
  };
  
  // 서버에 알림 읽음 처리 API 호출
  const markNotificationAsRead = async (notificationId: number) => {
    try {
      const token = localStorage.getItem('userToken');
      // 알림 읽음 API 호출 - API가 다를 수 있으므로 경로 확인 필요
      await axios.patch(
        `${API_BASE_URL}/alarm/read/${notificationId}`, 
        {}, 
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      console.log(`알림 ID: ${notificationId} 읽음 처리 성공`);
      return true;
    } catch (err) {
      console.error(`알림 ID: ${notificationId} 읽음 처리 실패:`, err);
      throw err;
    }
  };
  
  // 로컬에서 알림 읽음 처리
  const markNotificationAsReadLocally = (notificationId: number) => {
    // 기존 읽은 알림 목록 가져오기
    const readNotifications = getReadNotificationsFromStorage();
    
    // 이미 읽은 알림이 아니면 추가
    if (!readNotifications.includes(notificationId)) {
      readNotifications.push(notificationId);
      saveReadNotificationsToStorage(readNotifications);
    }
    
    // 현재 메모리의 알림 목록도 업데이트
    const updatedNotifications = notifications.map(notification => {
      if (notification.id === notificationId) {
        return { ...notification, isRead: true };
      }
      return notification;
    });
    
    setNotifications(updatedNotifications);
    
    // 읽지 않은 알림 수 업데이트
    const remainingUnreadCount = updatedNotifications.filter(notification => !notification.isRead).length;
    setUnreadCount(remainingUnreadCount);
  };
  
  // 모든 알림 읽음 처리
  const markAllAsRead = async () => {
    try {
      const token = localStorage.getItem('userToken');
      // 모든 알림 읽음 API 호출 - API가 있다면
      await axios.patch(
        `${API_BASE_URL}/alarm/readAll`,
        {},
        {
          headers: {
            'Content-Type': 'application/json',
            ...(token && { 'Authorization': `Bearer ${token}` })
          }
        }
      );
      
      // 로컬에서도 모든 알림 읽음 처리
      const allIds = notifications.map(notification => notification.id);
      const readNotifications = getReadNotificationsFromStorage();
      const newReadNotifications = [...new Set([...readNotifications, ...allIds])];
      saveReadNotificationsToStorage(newReadNotifications);
      
      // 메모리 상의 알림 목록 업데이트
      const updatedNotifications = notifications.map(notification => ({
        ...notification,
        isRead: true
      }));
      
      setNotifications(updatedNotifications);
      setUnreadCount(0);
      
    } catch (err) {
      console.error('모든 알림 읽음 처리 실패:', err);
      
      // API 실패해도 로컬에서는 읽음 처리
      const allIds = notifications.map(notification => notification.id);
      const readNotifications = getReadNotificationsFromStorage();
      const newReadNotifications = [...new Set([...readNotifications, ...allIds])];
      saveReadNotificationsToStorage(newReadNotifications);
      
      const updatedNotifications = notifications.map(notification => ({
        ...notification,
        isRead: true
      }));
      
      setNotifications(updatedNotifications);
      setUnreadCount(0);
    }
  };
  
  const handleViewAllNotifications = () => {
    navigate('/notifications');
    handleClose();
  };

  const fetchNotifications = async () => {
    setLoading(true);
    setError(null);
    
    try {
      const token = localStorage.getItem('userToken');
      
      // API 경로 수정 - 정확한 엔드포인트 확인
      const apiUrl = `${API_BASE_URL}/alarm/readAll`;
      console.log('API 호출 경로:', apiUrl);
      
      const response = await axios.get<AlarmDto[] | any>(apiUrl, {
        headers: {
          'Content-Type': 'application/json',
          ...(token && { 'Authorization': `Bearer ${token}` })
        }
      });
      
      // API 응답이 배열인지 확인
      const receivedData = response.data;
      console.log('받은 알림 데이터:', receivedData);
      
      // 로컬에 저장된 읽은 알림 ID 목록 가져오기
      const readNotificationIds = getReadNotificationsFromStorage();
      
      // 배열이 아닐 경우 데이터 구조 분석
      let processedNotifications: AlarmDto[] = [];
      
      if (!Array.isArray(receivedData)) {
        console.log('알림 데이터가 배열이 아닙니다. 데이터 구조:', typeof receivedData, receivedData);
        
        // 일반적인 API 응답 형식인 {data: [...]} 구조 확인
        if (receivedData && typeof receivedData === 'object' && 'data' in receivedData && Array.isArray(receivedData.data)) {
          processedNotifications = receivedData.data.map((item: AlarmDto) => ({
            ...item,
            isRead: readNotificationIds.includes(item.id)
          }));
        }
      } else {
        // 배열인 경우 그대로 사용하되, 로컬 읽음 상태 적용
        processedNotifications = receivedData.map((item: AlarmDto) => ({
          ...item,
          isRead: item.isRead || readNotificationIds.includes(item.id)
        }));
      }
      
      setNotifications(processedNotifications);
      
      // 읽지 않은 알림 수 계산
      const unreadNotifications = processedNotifications.filter(notification => !notification.isRead);
      setUnreadCount(unreadNotifications.length);
      
    } catch (err) {
      console.error('알림을 불러오는 중 오류가 발생했습니다:', err);
      setError('알림을 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  };

  // 컴포넌트 마운트 시 알림 목록 가져오기
  useEffect(() => {
    fetchNotifications();
    
    // 주기적으로 알림 업데이트 (선택 사항)
    const intervalId = setInterval(fetchNotifications, 60000); // 1분마다 갱신
    
    return () => clearInterval(intervalId);
  }, []);

  const open = Boolean(anchorEl);
  const id = open ? 'notifications-popover' : undefined;

  return (
    <>
      <IconButton
        aria-describedby={id}
        onClick={handleClick}
        color="primary"
      >
        <Badge 
          color="primary"
          variant="dot"
          invisible={unreadCount === 0} // 읽지 않은 알림이 없으면 표시하지 않음
        >
          <NotificationsOutlined />
        </Badge>
      </IconButton>
      
      <Popover
        id={id}
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
        PaperProps={{
          sx: { 
            width: '320px', 
            maxHeight: '400px',
            overflow: 'auto'
          }
        }}
      >
        <Box sx={{ 
          p: 2, 
          borderBottom: '1px solid #eee', 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center' 
        }}>
          <Typography variant="h6" fontWeight="medium">알림</Typography>
          <Box sx={{ display: 'flex', gap: 1 }}>
            {unreadCount > 0 && (
              <Button 
                size="small"
                onClick={markAllAsRead}
              >
                모두 읽음
              </Button>
            )}
            <Button 
              endIcon={<ArrowForward fontSize="small" />}
              onClick={handleViewAllNotifications}
              size="small"
            >
              전체보기
            </Button>
          </Box>
        </Box>
        
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
            <CircularProgress size={24} />
          </Box>
        ) : error ? (
          <Box sx={{ p: 2, color: 'error.main' }}>
            <Typography>{error}</Typography>
          </Box>
        ) : notifications.length === 0 ? (
          <Box sx={{ p: 3, textAlign: 'center' }}>
            <Typography color="text.secondary">알림이 없습니다.</Typography>
          </Box>
        ) : (
          <List sx={{ p: 0 }}>
            {Array.isArray(notifications) && notifications.slice(0, 5).map((notification) => (
              <React.Fragment key={notification.id}>
                <ListItem 
                  button 
                  alignItems="flex-start"
                  onClick={() => handleNotificationClick(notification)}
                  sx={{
                    p: 2,
                    backgroundColor: notification.isRead ? 'transparent' : 'rgba(25, 118, 210, 0.04)',
                    '&:hover': {
                      backgroundColor: notification.isRead 
                        ? 'rgba(0, 0, 0, 0.04)' 
                        : 'rgba(25, 118, 210, 0.08)',
                    },
                  }}
                >
                  <ListItemText
                    primary={
                      <Box sx={{ mb: 0.5 }}>
                        <Typography 
                          variant="body1"
                          sx={{ 
                            fontWeight: notification.isRead ? 'normal' : 'bold',
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            display: '-webkit-box',
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: 'vertical'
                          }}
                        >
                          {notification.content}
                        </Typography>
                      </Box>
                    }
                    secondary={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <AccessTime fontSize="small" sx={{ fontSize: '0.875rem', color: 'text.secondary' }} />
                        <Typography variant="body2" color="text.secondary">
                          {dayjs(notification.createDate).fromNow()}
                        </Typography>
                      </Box>
                    }
                  />
                </ListItem>
                <Divider />
              </React.Fragment>
            ))}
            
            {Array.isArray(notifications) && notifications.length > 5 && (
              <Box sx={{ p: 1.5, textAlign: 'center' }}>
                <Button 
                  variant="text" 
                  size="small" 
                  onClick={handleViewAllNotifications}
                >
                  더 보기 ({notifications.length - 5}개)
                </Button>
              </Box>
            )}
          </List>
        )}
      </Popover>
    </>
  );
};

export default Notifications; 