import React, { useState, useEffect } from 'react';
import { Box, Typography, Paper, Button, IconButton, Dialog, DialogTitle, DialogContent, DialogActions, TextField, RadioGroup, Radio, FormControlLabel, List, ListItem, ListItemText, ListItemAvatar, Avatar, Divider } from '@mui/material';
import { ArrowForwardIos } from '@mui/icons-material';
import { ReviewablePostDto } from '../types/manner'; // PostDto 대신 ReviewablePostDto 사용
import dayjs from 'dayjs';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:8080';

// Manner enum 추가
enum Manner {
  GOOD = "GOOD",
  NORMAL = "NORMAL",
  BAD = "BAD"
}

interface UserInfo {
  userId: number;
  studentId: string;
  profileImageUrl: string;
}

interface WritableReviewCardProps {
  post: ReviewablePostDto;
}

const WritableReviewCard: React.FC<WritableReviewCardProps> = ({ post }) => {
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [manner, setManner] = useState<Manner>(Manner.GOOD);
  const [content, setContent] = useState('');
  const [loading, setLoading] = useState(false);
  const [isDriver, setIsDriver] = useState(false);
  const [participants, setParticipants] = useState<UserInfo[]>([]);
  const [selectedParticipant, setSelectedParticipant] = useState<UserInfo | null>(null);

  useEffect(() => {
    const currentUserId = localStorage.getItem('userId');
    setIsDriver(post.user.id === Number(currentUserId));
  }, [post]);

  const handleWriteReview = async () => {
    if (isDriver) {
      // 운전자인 경우 참여자 목록을 가져옵니다
      try {
        const token = localStorage.getItem('userToken');
        const participantsInfo = await Promise.all(
          post.participants?.map(async (participant) => {
            const response = await axios.get(`${API_BASE_URL}/user/id/${participant.userId}`, {
              headers: {
                'Authorization': `Bearer ${token}`
              }
            });
            return {
              userId: participant.userId,
              studentId: response.data.studentId,
              profileImageUrl: response.data.profileImageUrl
            };
          }) || []
        );
        setParticipants(participantsInfo);
        setOpen(true);
      } catch (error) {
        console.error('참여자 정보 조회 실패:', error);
        alert('참여자 정보를 불러오는데 실패했습니다.');
      }
    } else {
      // 탑승자인 경우 기존 로직
      setOpen(true);
    }
  };

  const handleClose = () => {
    setOpen(false);
    setManner(Manner.GOOD);
    setContent('');
    setSelectedParticipant(null);
  };

  const handleParticipantSelect = (participant: UserInfo) => {
    setSelectedParticipant(participant);
  };

  const handleSubmit = async () => {
    if (!content.trim()) {
      alert('후기 내용을 입력해주세요.');
      return;
    }

    if (isDriver && !selectedParticipant) {
      alert('평가할 탑승자를 선택해주세요.');
      return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('userToken');
      const currentUserId = localStorage.getItem('userId');

      if (!currentUserId) {
        throw new Error('로그인이 필요합니다.');
      }

      if (isDriver) {
        // 운전자가 탑승자를 평가하는 로직
        const requestBody = {
          manner: manner,
          content: content.trim(),
          postId: post.postId,
          userId: Number(currentUserId)
        };

        await axios.post(
          `${API_BASE_URL}/post/${selectedParticipant?.userId}/evaluation/passenger`,
          requestBody,
          {
            headers: {
              'Content-Type': 'application/json',
              ...(token && { 'Authorization': `Bearer ${token}` })
            }
          }
        );

        // 평가 완료된 탑승자를 목록에서 제거
        setParticipants(prev => prev.filter(p => p.userId !== selectedParticipant?.userId));
        setSelectedParticipant(null);
        setContent('');
        setManner(Manner.GOOD);

        // 모든 탑승자 평가가 완료되었는지 확인
        if (participants.length === 1) { // 현재 평가 중인 탑승자가 마지막 탑승자
          alert('모든 탑승자 평가가 완료되었습니다.');
          handleClose();
          window.location.reload();
        } else {
          alert('후기가 작성되었습니다. 다음 탑승자를 평가해주세요.');
        }
      } else {
        // 탑승자가 기사를 평가하는 로직
        const requestBody = {
          manner: manner,
          content: content.trim(),
          userId: Number(currentUserId)
        };

        await axios.post(
          `${API_BASE_URL}/post/${post.postId}/evaluation/driver`,
          requestBody,
          {
            headers: {
              'Content-Type': 'application/json',
              ...(token && { 'Authorization': `Bearer ${token}` })
            }
          }
        );

        alert('후기가 작성되었습니다.');
        handleClose();
        window.location.reload();
      }
    } catch (error) {
      console.error('후기 작성 실패:', error);
      alert('후기 작성에 실패했습니다.');
    } finally {
      setLoading(false);
    }
  };

  const completedDate = post.targetDate 
    ? dayjs(post.targetDate).format('YYYY.MM.DD') 
    : '날짜 정보 없음';

  return (
    <>
      <Paper elevation={0} sx={{ width: '100%', boxSizing: 'border-box', p: 2, mb: 1, border: '1px solid #eee', borderRadius: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Box>
          <Typography variant="subtitle1" fontWeight="bold">{post.title}</Typography>
          <Typography variant="caption" color="text.secondary">
            카풀완료: {completedDate}
          </Typography>
          <Button 
            variant="text" 
            size="small" 
            onClick={handleWriteReview}
            sx={{ display: 'block', p:0, mt: 0.5, justifyContent:'flex-start' , color: 'primary.main'}}
          >
            후기 작성하러 가기
          </Button>
        </Box>
        <IconButton onClick={handleWriteReview} size="small">
          <ArrowForwardIos fontSize="small" />
        </IconButton>
      </Paper>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>
          {isDriver ? '탑승자 평가하기' : '기사님 평가하기'}
        </DialogTitle>
        <DialogContent>
          {isDriver ? (
            <>
              <Typography variant="subtitle1" gutterBottom sx={{ mt: 2 }}>
                평가할 탑승자 선택
              </Typography>
              <List>
                {participants.map((participant) => (
                  <React.Fragment key={participant.userId}>
                    <ListItem 
                      button 
                      selected={selectedParticipant?.userId === participant.userId}
                      onClick={() => handleParticipantSelect(participant)}
                    >
                      <ListItemAvatar>
                        <Avatar src={participant.profileImageUrl}>
                          {participant.studentId[0]}
                        </Avatar>
                      </ListItemAvatar>
                      <ListItemText 
                        primary={`학번: ${participant.studentId}`}
                      />
                    </ListItem>
                    <Divider />
                  </React.Fragment>
                ))}
              </List>
            </>
          ) : null}
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              매너 평가
            </Typography>
            <RadioGroup
              value={manner}
              onChange={(e) => setManner(e.target.value as Manner)}
            >
              <FormControlLabel value={Manner.GOOD} control={<Radio />} label="좋음" />
              <FormControlLabel value={Manner.NORMAL} control={<Radio />} label="보통" />
              <FormControlLabel value={Manner.BAD} control={<Radio />} label="나쁨" />
            </RadioGroup>
          </Box>
          <TextField
            fullWidth
            multiline
            rows={4}
            label="후기 내용"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>취소</Button>
          <Button 
            onClick={handleSubmit} 
            variant="contained" 
            disabled={loading || !content.trim() || (isDriver && !selectedParticipant)}
          >
            {loading ? '작성 중...' : '작성하기'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default WritableReviewCard; 